def _load_m27_brands() -> tuple[list[str], dict[str, dict[str, Any]]]:
    """Decode embedded PNGs and assert each sha256 matches the manifest."""
    try:
        manifest = json.loads(_M27_ICONS_JSON)
    except json.JSONDecodeError as e:
        raise SystemExit(f"[{APP}] embedded brand manifest is not JSON: {e}") from e
    if not isinstance(manifest, dict) or manifest.get("m27_icons") != 1:
        raise SystemExit(f"[{APP}] embedded brand manifest is not m27_icons v1")
    icons = manifest.get("icons")
    if not isinstance(icons, list):
        raise SystemExit(f"[{APP}] embedded brand manifest must list icons")
    # Catalog owns the 8 duplicates. They stay in the embedded JSON but are not loaded.
    icons = [
        row for row in icons
        if not (isinstance(row, dict) and row.get("name") in _DROPPED_BRAND_CATALOG)
    ]
    if len(icons) != 10:
        raise SystemExit(f"[{APP}] embedded brand manifest must list 10 gap icons")
    order: list[str] = []
    table: dict[str, dict[str, Any]] = {}
    for row in icons:
        if not isinstance(row, dict):
            raise SystemExit(f"[{APP}] brand icon row is not an object")
        name = row.get("name")
        digest = row.get("sha256")
        b64 = row.get("png_b64")
        label = row.get("label")
        if (
            not isinstance(name, str)
            or not name
            or not isinstance(digest, str)
            or not isinstance(b64, str)
            or not isinstance(label, str)
            or not label.strip()
        ):
            raise SystemExit(f"[{APP}] brand icon row missing name/label/sha256/png_b64")
        if name in table:
            raise SystemExit(f"[{APP}] duplicate brand icon {name}")
        try:
            raw = base64.b64decode(b64, validate=True)
        except Exception as e:
            raise SystemExit(f"[{APP}] brand icon {name} is not valid base64: {e}") from e
        got = hashlib.sha256(raw).hexdigest()
        if got != digest:
            raise SystemExit(
                f"[{APP}] brand icon {name} sha256 mismatch: got {got} expected {digest}"
            )
        order.append(name)
        table[name] = {
            "name": name,
            "label": label.strip(),
            "source": row.get("source"),
            "file": row.get("file"),
            "license": row.get("license"),
            "sha256": digest,
            "png": raw,
        }
    return order, table


