def data_dir() -> Path:
    """Local data root: BENDWRIGHT_DATA_DIR when set, else <script>/bendwright-data."""
    override = os.environ.get("BENDWRIGHT_DATA_DIR", "").strip()
    if override:
        return Path(override).expanduser().resolve()
    return Path(__file__).resolve().parent / "bendwright-data"


def user_icons_dir() -> Path:
    """bendwright-data/icons (or BENDWRIGHT_DATA_DIR/icons)."""
    return data_dir() / "icons"


def migrate_legacy_data_dir() -> str | None:
    """One-time copy from ~/.bendwright into data_dir(). Never moves or deletes.

    Runs only when the new data dir does not exist yet and the legacy folder
    does. Never raises.
    """
    global _data_dir_note
    dest = data_dir()
    try:
        if dest.exists():
            return None
    except OSError:
        return None
    legacy = Path.home() / ".bendwright"
    try:
        if not legacy.is_dir():
            return None
    except OSError:
        return None
    try:
        dest.mkdir(parents=True, exist_ok=True)
        legacy_icons = legacy / "icons"
        try:
            has_icons = legacy_icons.is_dir()
        except OSError:
            has_icons = False
        if has_icons:
            icons_dest = dest / "icons"
            icons_dest.mkdir(parents=True, exist_ok=True)
            try:
                entries = list(legacy_icons.iterdir())
            except OSError:
                entries = []
            for path in entries:
                try:
                    if not path.is_file() or path.suffix.lower() != ".png":
                        continue
                except OSError:
                    continue
                target = icons_dest / path.name
                if target.exists():
                    continue
                shutil.copy2(path, target)
        for name in ("types.json", "archify-patch-state.json"):
            src = legacy / name
            try:
                if not src.is_file():
                    continue
            except OSError:
                continue
            target = dest / name
            if target.exists():
                continue
            shutil.copy2(src, target)
        note = (
            f"copied your old ~/.bendwright data to {dest}; "
            "the old folder was left in place"
        )
        _data_dir_note = note
        return note
    except OSError:
        return None


def note_data_dir_writable() -> str | None:
    """Status note when the data dir cannot be written. Never raises."""
    global _data_dir_note
    folder = data_dir()
    if _dir_writable(folder):
        return None
    note = (
        f"data dir not writable: {folder}; "
        "set BENDWRIGHT_DATA_DIR to an absolute writable path"
    )
    if not _data_dir_note:
        _data_dir_note = note
    return note


def _clean_viewbox(value: Any) -> int | float | str | None:
    """Square number, or a 'minx miny w h' string. Anything else is dropped."""
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        if value > 0 and value == value:
            if isinstance(value, float) and value.is_integer():
                return int(value)
            return value
        return None
    if not isinstance(value, str):
        return None
    text = " ".join(value.split())
    if not text:
        return None
    parts = text.split(" ")
    try:
        nums = [float(part) for part in parts]
    except ValueError:
        return None
    if len(nums) == 1 and nums[0] > 0:
        return int(nums[0]) if nums[0].is_integer() else nums[0]
    if len(nums) == 4 and nums[2] > 0 and nums[3] > 0:
        return text
    return None


def _clean_hex(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if text.startswith("#"):
        text = text[1:]
    if not text or any(ch not in "0123456789abcdefABCDEF" for ch in text):
        return None
    if len(text) == 3:
        text = "".join(ch * 2 for ch in text)
    if len(text) != 6:
        return None
    return text


def _clean_path(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not text or len(text) > 50000 or "<" in text or ">" in text:
        return None
    return text


def _shape_of_mark(row: dict[str, Any]) -> dict[str, Any]:
    """Top-level {viewBox, hex, path}, else the same keys under custom. Path required."""
    sources: list[Any] = [row, row.get("custom")]
    for source in sources:
        if not isinstance(source, dict):
            continue
        path = _clean_path(source.get("path"))
        if not path:
            continue
        shape: dict[str, Any] = {"path": path}
        viewbox = _clean_viewbox(source.get("viewBox"))
        if viewbox is not None:
            shape["viewBox"] = viewbox
        color = _clean_hex(source.get("hex"))
        if color:
            shape["hex"] = color
        return shape
    return {}


def _json_bracket_slice(text: str, start: int) -> str | None:
    """Slice a JSON array/object starting at start. Strings are respected. None if unbalanced."""
    if start < 0 or start >= len(text) or text[start] not in "[{":
        return None
    depth = 0
    in_str = False
    escaped = False
    opener = text[start]
    closer = "]" if opener == "[" else "}"
    for index in range(start, len(text)):
        ch = text[index]
        if in_str:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch in "[{":
            depth += 1
        elif ch in "]}":
            depth -= 1
            if depth == 0:
                if ch != closer:
                    return None
                return text[start : index + 1]
            if depth < 0:
                return None
    return None


def _generated_brand_shapes(root: Path) -> dict[str, dict[str, Any]]:
    """Shape data from generated-brand-marks.mjs. JSON parse only; never executed.

    Unreadable, non-JSON, or not a frozen array: empty dict (caller keeps names).
    """
    path = root / "renderers" / "shared" / "generated-brand-marks.mjs"
    try:
        if not path.is_file() or path.stat().st_size > 20 * 1024 * 1024:
            return {}
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return {}
    marker = "Object.freeze("
    idx = text.find(marker)
    if idx < 0:
        return {}
    bracket = text.find("[", idx)
    if bracket < 0:
        return {}
    blob = _json_bracket_slice(text, bracket)
    if not blob:
        return {}
    try:
        data = json.loads(blob)
    except json.JSONDecodeError:
        return {}
    if not isinstance(data, list):
        return {}
    shapes: dict[str, dict[str, Any]] = {}
    for row in data:
        if not isinstance(row, dict):
            continue
        mark_id = row.get("id")
        if not isinstance(mark_id, str) or not mark_id or mark_id in shapes:
            continue
        shape = _shape_of_mark(row)
        if shape:
            shapes[mark_id] = shape
    return shapes


def load_archify_catalog(archify_mjs: str | None) -> None:
    """Read brand-marks/catalog.json from the resolved archify. Never raises.

    List comes only from catalog.json (id, title, aliases, category). Shape is
    the mark's own viewBox/hex/path, or custom.*, or — only when that is missing —
    generated-brand-marks.mjs. Missing catalog: status note, empty list, free-text field.
    """
    global _catalog_marks, _catalog_ids, _catalog_note
    _catalog_marks = []
    _catalog_ids = set()
    _catalog_note = None
    if not archify_mjs:
        _catalog_note = _CATALOG_UNREADABLE
        return
    try:
        root = archify_skill_root(archify_mjs)
        path = root / "brand-marks" / "catalog.json"
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError):
        _catalog_note = _CATALOG_UNREADABLE
        return
    marks = data.get("marks") if isinstance(data, dict) else None
    if not isinstance(marks, list):
        _catalog_note = _CATALOG_UNREADABLE
        return
    try:
        shapes = _generated_brand_shapes(root)
    except Exception:
        shapes = {}
    loaded: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in marks:
        if not isinstance(row, dict):
            continue
        mark_id = row.get("id")
        if not isinstance(mark_id, str) or not mark_id or mark_id in seen:
            continue
        title = row.get("title")
        if not isinstance(title, str) or not title.strip():
            title = mark_id
        item: dict[str, Any] = {"id": mark_id, "title": title.strip()}
        category = row.get("category")
        if isinstance(category, str) and category.strip():
            item["category"] = category.strip()
        aliases_raw = row.get("aliases")
        if isinstance(aliases_raw, list):
            aliases = [alias.strip() for alias in aliases_raw if isinstance(alias, str) and alias.strip()]
            if aliases:
                item["aliases"] = aliases
        shape = _shape_of_mark(row)
        if not shape:
            shape = shapes.get(mark_id) or {}
        item.update(shape)
        seen.add(mark_id)
        loaded.append(item)
    _catalog_marks = loaded
    _catalog_ids = seen
    if not loaded:
        _catalog_note = _CATALOG_UNREADABLE


def catalog_api_payload() -> dict[str, Any]:
    """Lean catalog preview. No domains, provenance, or simpleIcon slugs."""
    payload: dict[str, Any] = {
        "ok": True,
        "catalog": list(_catalog_marks),
        "catalog_ok": bool(_catalog_marks),
    }
    if _catalog_note:
        payload["note"] = _catalog_note
    return payload


def scan_user_icons() -> str | None:
    """Load bendwright-data/icons. Bad files are skipped. Does not raise.

    Creates the icons folder on first scan when the data dir is writable.
    Built-in gap names and catalog ids win a clash. Stem must already match;
    names are not rewritten. PNG magic and a 64 KB cap.
    """
    global _user_icons, _user_icon_note
    table: dict[str, dict[str, Any]] = {}
    notes: list[str] = []
    folder = user_icons_dir()
    try:
        folder.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    try:
        exists = folder.is_dir()
    except OSError:
        exists = False
    if not exists:
        _user_icons = {}
        _user_icon_note = None
        return None
    try:
        entries = sorted(folder.iterdir(), key=lambda p: p.name.lower())
    except OSError as e:
        _user_icons = {}
        _user_icon_note = f"icons folder unreadable: {e}"
        return _user_icon_note
    for path in entries:
        try:
            if not path.is_file():
                continue
        except OSError:
            continue
        stem = path.stem
        if not _USER_ICON_RE.fullmatch(stem):
            notes.append(
                f"icon skipped: {path.name} (name must match ^[a-z0-9][a-z0-9_-]*$)"
            )
            continue
        if stem in _BRANDS or stem in _catalog_ids:
            notes.append(f"icon skipped: {stem} (built-in or catalog name)")
            continue
        try:
            raw = path.read_bytes()
        except OSError as e:
            notes.append(f"icon skipped: {path.name} ({e})")
            continue
        if not raw.startswith(_PNG_MAGIC):
            notes.append(f"icon skipped: {path.name} (not a PNG)")
            continue
        if len(raw) > _USER_ICON_MAX:
            notes.append(f"icon skipped: {path.name} (over 64 KB)")
            continue
        table[stem] = {
            "name": stem,
            "label": stem,
            "sha256": hashlib.sha256(raw).hexdigest(),
            "png": raw,
            "source": "user",
        }
    _user_icons = table
    _user_icon_note = "; ".join(notes) if notes else None
    return _user_icon_note


def _sidecar_icon_bytes(name: str, sidecar: dict[str, Any] | None) -> tuple[bytes, str] | None:
    """PNG bytes stored on the sidecar for a user icon. Folder is not consulted."""
    if not isinstance(sidecar, dict):
        return None
    icons = sidecar.get("icons")
    if not isinstance(icons, dict):
        return None
    entry = icons.get(name)
    if not isinstance(entry, dict):
        return None
    b64 = entry.get("b64")
    digest = entry.get("sha256")
    if not isinstance(b64, str) or not isinstance(digest, str):
        return None
    try:
        raw = base64.b64decode(b64, validate=True)
    except Exception:
        return None
    if not raw.startswith(_PNG_MAGIC):
        return None
    if hashlib.sha256(raw).hexdigest() != digest:
        return None
    return raw, digest


def _icon_asset(name: str, sidecar: dict[str, Any] | None = None) -> dict[str, Any] | None:
    """Gap PNG, user PNG, or sidecar bytes. Catalog ids and dropped names are not assets.

    Folder wins over a sidecar blob with the same name.
    """
    if not name or name in _DROPPED_BRAND_CATALOG:
        return None
    row = _BRANDS.get(name)
    if row is not None:
        return row
    user = _user_icons.get(name)
    if user is not None:
        return user
    blob = _sidecar_icon_bytes(name, sidecar)
    if blob is None:
        return None
    raw, digest = blob
    return {"name": name, "label": name, "sha256": digest, "png": raw, "source": "sidecar"}


def _user_icon_blob(name: str) -> dict[str, str] | None:
    row = _user_icons.get(name)
    if row is None:
        return None
    return {
        "sha256": str(row["sha256"]),
        "b64": base64.b64encode(row["png"]).decode("ascii"),
    }


def _brand_icon_names(doc: dict[str, Any] | None) -> list[str]:
    """Icon names from node or component brand URLs on this loopback. Document order."""
    names: list[str] = []
    if not isinstance(doc, dict):
        return names
    for node in _element_list(doc):
        if not isinstance(node, dict):
            continue
        brand = node.get("brand")
        if not isinstance(brand, dict):
            continue
        url = brand.get("url")
        if not isinstance(url, str):
            continue
        match = _OUR_BRAND_URL_RE.match(url)
        if not match:
            continue
        name = match.group(1)
        if name not in names:
            names.append(name)
    return names


def _sync_sidecar_icons(sidecar: dict[str, Any], doc: dict[str, Any] | None = None) -> None:
    """Keep icons blobs for type icons and brand URLs this diagram uses.

    Folder bytes win. A missing folder file keeps the previous blob so render
    still works. Empty icons are removed and do not force a sidecar file.
    Gap, catalog, and dropped names are not stored.
    """
    types = sidecar.get("types")
    used: list[str] = []
    if isinstance(types, dict):
        for entry in types.values():
            if isinstance(entry, dict) and isinstance(entry.get("icon"), str):
                icon = entry["icon"]
                if icon not in used:
                    used.append(icon)
    for name in _brand_icon_names(doc):
        if name not in used:
            used.append(name)
    previous = sidecar.get("icons") if isinstance(sidecar.get("icons"), dict) else {}
    nxt: dict[str, Any] = {}
    for name in used:
        if name in _BRANDS or name in _catalog_ids or name in _DROPPED_BRAND_CATALOG:
            continue
        blob = _user_icon_blob(name)
        if blob is not None:
            nxt[name] = blob
            continue
        old = previous.get(name) if isinstance(previous, dict) else None
        if (
            isinstance(old, dict)
            and isinstance(old.get("b64"), str)
            and isinstance(old.get("sha256"), str)
        ):
            nxt[name] = {"sha256": old["sha256"], "b64": old["b64"]}
    if nxt:
        sidecar["icons"] = nxt
    else:
        sidecar.pop("icons", None)


def _migrate_type_icons(types: Any) -> list[str]:
    """Rename postgres/node/gcp in memory. Does not write. Other dropped ids stay."""
    notes: list[str] = []

    def one(entry: Any, label: str) -> None:
        if not isinstance(entry, dict):
            return
        icon = entry.get("icon")
        if not isinstance(icon, str):
            return
        nxt = _ICON_RENAMES.get(icon)
        if not nxt:
            return
        entry["icon"] = nxt
        notes.append(f"{label} icon {icon} -> {nxt}")

    if isinstance(types, dict):
        for type_id, entry in types.items():
            one(entry, str(type_id))
    elif isinstance(types, list):
        for entry in types:
            type_id = entry.get("id") if isinstance(entry, dict) else "?"
            one(entry, str(type_id))
    return notes


def _icon_rename_note(parts: list[str]) -> str | None:
    if not parts:
        return None
    return "type icon renamed: " + "; ".join(parts)


def _dropped_brand_offer_note(doc: dict[str, Any]) -> str | None:
    """Count loopback brands for a dropped icon. Does not change the doc or dirty it."""
    if not isinstance(doc, dict):
        return None
    count = 0
    for node in _element_list(doc):
        if not isinstance(node, dict):
            continue
        brand = node.get("brand")
        if not isinstance(brand, dict):
            continue
        url = brand.get("url")
        if not isinstance(url, str):
            continue
        match = _OUR_BRAND_URL_RE.match(url)
        if match and match.group(1) in _DROPPED_BRAND_CATALOG:
            count += 1
    if not count:
        return None
    return (
        f"{count} brand(s) still use a removed icon URL; "
        "re-apply the type to store the catalog id"
    )


def blank_workflow() -> dict[str, Any]:
    """Smallest workflow IR archify 2.17 validates. Shared by no-arg start and New."""
    return {
        "schema_version": 2,
        "diagram_type": "workflow",
        "meta": {"title": "Untitled diagram"},
        "lanes": [{"id": "lane1", "label": "Lane"}],
        "nodes": [
            {
                "id": "node1",
                "lane": "lane1",
                "col": 0,
                "type": "backend",
                "label": "New node",
            }
        ],
        "edges": [],
        "cards": [],
    }


def blank_architecture() -> dict[str, Any]:
    """Smallest architecture IR. No layout key. One free-positioned component."""
    return {
        "schema_version": 1,
        "diagram_type": "architecture",
        "meta": {"title": "Untitled diagram"},
        "components": [
            {
                "id": "component1",
                "type": "backend",
                "label": "New component",
                "pos": [40, 80],
                "size": [120, 60],
            }
        ],
    }


def blank_diagram(diagram_type: str) -> dict[str, Any]:
    if diagram_type == "architecture":
        return blank_architecture()
    return blank_workflow()


