_TEMPLATES: dict[str, Any] = dict(_TEMPLATE_PACK["templates"])


def template_document(template_id: str) -> dict[str, Any] | None:
    """Return a deep copy so session edits never mutate the embedded template."""
    raw = _TEMPLATES.get(template_id)
    if not isinstance(raw, dict):
        return None
    return copy.deepcopy(raw)


def ir_collection_keys(diagram_type: str) -> tuple[str, ...]:
    if diagram_type == "architecture":
        return ARCHITECTURE_IR_KEYS
    return IR_KEYS


def save_name_suffix(diagram_type: str) -> str:
    if diagram_type == "architecture":
        return ".architecture.json"
    return ".workflow.json"


def resolve_diagram_type(doc: dict[str, Any] | None, fallback: str) -> str:
    """Supported type on the document, else the session type, else workflow."""
    inferred = doc.get("diagram_type") if isinstance(doc, dict) else None
    if isinstance(inferred, str) and inferred in ("workflow", "architecture"):
        return inferred
    if fallback in ("workflow", "architecture"):
        return fallback
    return "workflow"


def current_listen_port() -> int:
    """Port archify should use when fetching /brand/<name>.png."""
    httpd = _httpd
    if httpd is not None:
        try:
            return int(httpd.server_address[1])
        except (TypeError, ValueError, OSError):
            pass
    return _listen_port


def brand_public_url(name: str, port: int | None = None) -> str:
    use = current_listen_port() if port is None else port
    return f"http://127.0.0.1:{use}/brand/{name}.png"


def brands_api_payload() -> list[dict[str, str]]:
    """Gap icons then user PNGs. Catalog ids are not loopback URLs."""
    port = current_listen_port()
    rows: list[dict[str, str]] = []
    for name in _BRAND_ORDER:
        rows.append(
            {
                "name": name,
                "url": brand_public_url(name, port),
                "sha256": _BRANDS[name]["sha256"],
                "source": "bendwright",
                "label": str(_BRANDS[name].get("label") or name),
            }
        )
    for name in sorted(_user_icons):
        row = _user_icons[name]
        rows.append(
            {
                "name": name,
                "url": brand_public_url(name, port),
                "sha256": str(row["sha256"]),
                "source": "user",
                "label": name,
            }
        )
    return rows


def _icon_miss_sentence(name: str) -> str:
    return f"Icon not found: {name}. Showing the type symbol instead."


def _icon_miss_note(names: list[str] | None) -> str | None:
    if not names:
        return None
    return "\n".join(_icon_miss_sentence(name) for name in names)


def _apply_icon_miss_chips(html: bytes, names: list[str] | None) -> bytes:
    """Fixed chips on the delivered page. Out of flow so they cannot resize the svg."""
    if not names:
        return html
    try:
        text = html.decode("utf-8")
    except UnicodeError:
        return html
    chips: list[str] = []
    for index, name in enumerate(names):
        top = 8 + index * 36
        chips.append(
            '<p class="bw-icon-miss" role="status" style="'
            f"position:fixed;top:{top}px;left:12px;z-index:30;margin:0;"
            "padding:6px 10px;border-radius:999px;background:#1C242C;"
            "color:#E7E4DC;font:13px/1.3 system-ui,sans-serif;"
            'border:1px solid #343C46">'
            f"{html_escape(_icon_miss_sentence(name))}</p>"
        )
    block = "".join(chips)
    close = re.search(r"</body>", text, re.IGNORECASE)
    if close:
        text = text[: close.start()] + block + text[close.start() :]
    else:
        text += block
    return text.encode("utf-8")


def _rewrite_brands_for_archify(
    doc: dict[str, Any], sidecar: dict[str, Any] | None = None
) -> tuple[dict[str, Any], list[str]]:
    """Copy doc. Dropped loopback brands become catalog id strings.

    Gap and user PNGs are retargeted at this port and their sha256 refreshed.
    Catalog string brands are left alone. A loopback brand whose icon is not
    in the sidecar and not on disk is removed from the copy only. The caller's
    doc is not mutated. The second value is the missing icon names, in order.
    """
    out = copy.deepcopy(doc)
    elements = _element_list(out)
    if not elements:
        return out, []
    missing: list[str] = []
    port = current_listen_port()
    for node in elements:
        if not isinstance(node, dict):
            continue
        brand = node.get("brand")
        if not isinstance(brand, dict):
            continue
        url = brand.get("url")
        if not isinstance(url, str):
            continue
        match = _OUR_BRAND_URL_RE.match(url)
        if not match:
            continue
        name = match.group(1)
        catalog_id = _DROPPED_BRAND_CATALOG.get(name)
        if catalog_id:
            node["brand"] = catalog_id
            continue
        icon = _icon_asset(name, sidecar)
        if icon is None:
            node.pop("brand", None)
            if name not in missing:
                missing.append(name)
            continue
        brand["url"] = brand_public_url(name, port)
        brand["sha256"] = icon["sha256"]
    return out, missing


def read_installed_archify_version(archify_mjs: str) -> str | None:
    """package.json beside archify.mjs, else the parent package root."""
    base = Path(archify_mjs).resolve().parent
    for candidate in (base / "package.json", base.parent / "package.json"):
        try:
            if not candidate.is_file():
                continue
            data = json.loads(candidate.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            continue
        if isinstance(data, dict):
            version = data.get("version")
            if isinstance(version, str) and version.strip():
                return version.strip()
    return None


def note_archify_version(archify_mjs: str | None) -> None:
    """Record a status note on version mismatch. Never a startup failure."""
    global _archify_version_note
    _archify_version_note = None
    if not archify_mjs:
        return
    found = read_installed_archify_version(archify_mjs)
    if found is None:
        _archify_version_note = (
            "Could not read archify package.json beside "
            f"{archify_mjs}; bendwright last verified brand icons against "
            f"{LAST_VERIFIED_ARCHIFY}."
        )
        return
    if found != LAST_VERIFIED_ARCHIFY:
        _archify_version_note = (
            f"Installed archify is {found}; bendwright last verified brand icons against "
            f"{LAST_VERIFIED_ARCHIFY}."
        )


# ---------------------------------------------------------------------------
# Shared runtime state (set in main)
# ---------------------------------------------------------------------------
_state_lock = threading.Lock()
_file_path: Path | None = None
_diagram_type: str = "workflow"
_doc: dict[str, Any] = {}
# Optional collection keys missing on the document that was opened or seeded.
_absent_empty_keys: set[str] = set()
_had_trailing_newline: bool = True
_archify_path: str | None = None
_preview_html: bytes | None = None
_diagram_html: bytes | None = None
# Loopback port baked into /api/brands URLs. main() sets this from the bound port.
_listen_port: int = 8770
# Identity of the diagram this process is editing. gen bumps on Open, New,
# template, and Discard reload. Save As of a new diagram changes the file
# only, so the tab that saved can adopt the new path without a bump.
_session_gen: int = 1
_PORT_WINDOW_LO = 8770
_PORT_WINDOW_HI = 8789
STALE_TAB_MSG = (
    "This tab is out of date: the diagram was switched in another tab. "
    "Reload to continue."
)
_SESSION_HEADER = "X-Bendwright-Session"
# M27: status note when the installed archify is not the version we verified.
_archify_version_note: str | None = None
# M29: resolved-tree kind-label patch. "patched" | "applied" | "opted-out" | "unpatched".
_archify_patch_note: str | None = None
_archify_patch_state: str = "unpatched"
# M28a style overlay. Sibling file, not a key in the workflow JSON.
_sidecar: dict[str, Any] = {
    "bendwright_sidecar": 1,
    "edges": {},
    "nodes": {},
    "types": {},
    "assignments": {},
}
_sidecar_note: str | None = None
_sidecar_unreadable: bool = False

# M18: short-request inflight accounting. Not a shutdown signal (M22 uses SSE presence).
_httpd: ThreadingHTTPServer | None = None
_inflight: int = 0
_inflight_lock = threading.Lock()

# M22: one held /api/alive SSE per tab. Auto-exit only after the last one drops.
ALIVE_KEEPALIVE_S = 5.0
ALIVE_GRACE_S = 25.0
_alive: int = 0
_alive_lock = threading.Lock()
_alive_seen: bool = False
_last_zero_ts: float | None = None
_auto_exit: bool = True


def _begin_request() -> None:
    """Enter a short request. Inflight does not affect M22 shutdown."""
    global _inflight
    with _inflight_lock:
        _inflight += 1


def _end_request() -> None:
    """Leave a short request."""
    global _inflight
    with _inflight_lock:
        _inflight -= 1


def detect_archify(cli_path: str | None) -> tuple[str | None, str]:
    """Resolve archify.mjs (first hit wins). Returns (path_or_None, banner_detail)."""
    candidates: list[Path] = []
    if cli_path:
        candidates.append(Path(cli_path))
    env_home = os.environ.get("ARCHIFY_HOME")
    if env_home:
        home = Path(env_home)
        candidates.append(home)
        candidates.append(home / "bin" / "archify.mjs")
    user_home = Path(os.environ.get("USERPROFILE") or os.path.expanduser("~"))
    # Neutral resolution order: alongside this script, a sibling "archify"
    # checkout, the current directory, then the user's home directory.
    here = Path(__file__).resolve().parent
    for base in (here, here.parent, Path.cwd(), user_home):
        candidates.append(base / "archify" / "bin" / "archify.mjs")
        candidates.append(base / "archify.mjs")
    candidates.append(Path("bin") / "archify.mjs")
    on_path = shutil.which("archify")
    if on_path:
        candidates.append(Path(on_path))

    found: str | None = None
    for c in candidates:
        try:
            if c.is_file():
                found = str(c.resolve())
                break
        except OSError:
            continue

    if not found:
        return None, "none (no archify.mjs found; structural-check save, no preview)"
    if not shutil.which("node"):
        return None, "none (archify found but node not on PATH; structural-check save, no preview)"
    return found, found


def load_doc(path: Path) -> tuple[dict[str, Any], bool]:
    raw = path.read_text(encoding="utf-8")
    trailing = raw.endswith("\n")
    doc = json.loads(raw)
    if not isinstance(doc, dict):
        raise SystemExit(f"[{APP}] IR root must be a JSON object: {path}")
    return doc, trailing


def _diagram_save_path(
    raw: Any,
    diagram_type: str,
    *,
    base_dir: Path | None = None,
) -> tuple[Path | None, str | None]:
    """Resolve a save path. Appends the type suffix when missing.

    Relative paths resolve against base_dir (current file's folder), else cwd.
    Missing parent folder returns an error and does not create it.
    """
    if not isinstance(raw, str) or not raw.strip():
        return None, "path is required"
    suffix = save_name_suffix(diagram_type)
    try:
        target = Path(raw.strip()).expanduser()
        if not target.is_absolute():
            root = base_dir if isinstance(base_dir, Path) else Path.cwd()
            target = root / target
        target = target.resolve()
    except (OSError, RuntimeError) as e:
        return None, f"bad path: {e}"
    if not target.name.endswith(suffix):
        target = Path(str(target) + suffix)
    if not target.parent.is_dir():
        return None, f"folder does not exist: {target.parent}"
    return target, None


def _export_html_save_path(
    raw: Any, *, base_dir: Path | None = None
) -> tuple[Path | None, str | None]:
    """Resolve an HTML export path. Appends .html when missing."""
    if not isinstance(raw, str) or not raw.strip():
        return None, "path is required"
    try:
        target = Path(raw.strip()).expanduser()
        if not target.is_absolute():
            root = base_dir if isinstance(base_dir, Path) else Path.cwd()
            target = root / target
        target = target.resolve()
    except (OSError, RuntimeError) as e:
        return None, f"bad path: {e}"
    if not target.name.lower().endswith(".html"):
        target = Path(str(target) + ".html")
    if not target.parent.is_dir():
        return None, f"folder does not exist: {target.parent}"
    return target, None


_EXPORT_THEME_VALUES = frozenset({"dark", "light", "system"})
_EXPORT_THEME_DEFAULT = "dark"
_EXPORT_THEME_MARK = b"/*bw-export-theme*/"
_LOCALSTORAGE_THEME_ANCHOR = (
    b"if (!theme) {\n"
    b"          try { theme = localStorage.getItem('archify-theme'); } catch (_) {}\n"
    b"        }"
)
# Archify.theme re-applies after the pre-paint script. These two anchors are
# the URL-check-then-readStored shape in the stock toolbar script.
_RESOLVE_INITIAL_ANCHOR = (
    b"        if (fromUrl) return fromUrl;\n"
    b"        var saved = readStored();"
)
_ONCHANGE_THEME_ANCHOR = (
    b"        var onChange = function (e) {\n"
    b"          var saved = readStored();"
)


def normalize_export_theme(raw: Any) -> str:
    """dark | light | system. Unknown values fall back to dark."""
    if isinstance(raw, str):
        value = raw.strip().lower()
        if value in _EXPORT_THEME_VALUES:
            return value
    return _EXPORT_THEME_DEFAULT


_EXPORT_THEME_INJECT_RE = re.compile(
    br"if \(!theme\) \{ theme = '(?:dark|light)'; \} /\*bw-export-theme\*/\r?\n[ \t]*"
)
_EXPORT_THEME_RESOLVE_RE = re.compile(
    br"        return '(?:dark|light)'; /\*bw-theme-resolve\*/\r?\n"
)
_EXPORT_THEME_ONCHANGE_RE = re.compile(
    br"          return; /\*bw-theme-onchange\*/\r?\n"
)


def apply_export_theme(html: bytes, theme: str) -> bytes:
    """Bake dark/light into Archify's pre-paint script and Archify.theme.

    system leaves bytes alone. ?theme= still wins in both places. toggle()
    is left intact so a click still flips and stores. A missing anchor skips
    that patch only; export still returns the other patches.
    """
    if not isinstance(html, (bytes, bytearray)):
        return html
    chosen = normalize_export_theme(theme)
    raw = bytes(html)
    raw = _EXPORT_THEME_INJECT_RE.sub(b"", raw)
    raw = _EXPORT_THEME_RESOLVE_RE.sub(b"", raw)
    raw = _EXPORT_THEME_ONCHANGE_RE.sub(b"", raw)
    if chosen == "system":
        return raw
    if _LOCALSTORAGE_THEME_ANCHOR in raw:
        injection = (
            f"if (!theme) {{ theme = '{chosen}'; }} /*bw-export-theme*/\n        ".encode(
                "ascii"
            )
            + _LOCALSTORAGE_THEME_ANCHOR
        )
        raw = raw.replace(_LOCALSTORAGE_THEME_ANCHOR, injection, 1)
    if _RESOLVE_INITIAL_ANCHOR in raw:
        # Return the baked theme after the URL check and before readStored.
        resolve_line = f"        return '{chosen}'; /*bw-theme-resolve*/\n".encode(
            "ascii"
        )
        raw = raw.replace(
            _RESOLVE_INITIAL_ANCHOR,
            b"        if (fromUrl) return fromUrl;\n"
            + resolve_line
            + b"        var saved = readStored();",
            1,
        )
    if _ONCHANGE_THEME_ANCHOR in raw:
        # OS media changes must not override a baked theme. toggle() is separate.
        raw = raw.replace(
            _ONCHANGE_THEME_ANCHOR,
            b"        var onChange = function (e) {\n"
            b"          return; /*bw-theme-onchange*/\n"
            b"          var saved = readStored();",
            1,
        )
    return raw


def export_prefs_from_sidecar(sidecar: dict[str, Any] | None) -> dict[str, str]:
    """Return {theme, path} with defaults. path may be empty."""
    theme = _EXPORT_THEME_DEFAULT
    path = ""
    if isinstance(sidecar, dict):
        block = sidecar.get("export")
        if isinstance(block, dict):
            theme = normalize_export_theme(block.get("theme"))
            raw_path = block.get("path")
            if isinstance(raw_path, str) and raw_path.strip():
                path = raw_path.strip()
    return {"theme": theme, "path": path}


def resolve_sidecar_export_path(
    stored: str, ir_path: Path | None
) -> str:
    """Absolute path for a remembered export path. Relative → next to the JSON."""
    if not stored:
        if ir_path is not None:
            return str(export_html_path(ir_path))
        return ""
    try:
        target = Path(stored).expanduser()
        if not target.is_absolute() and ir_path is not None:
            target = ir_path.parent / target
        return str(target.resolve())
    except (OSError, RuntimeError):
        if ir_path is not None:
            return str(export_html_path(ir_path))
        return stored


def path_for_sidecar_export(html_path: Path, ir_path: Path) -> str:
    """Prefer a path relative to the JSON folder when the HTML lives inside it."""
    try:
        rel = html_path.resolve().relative_to(ir_path.parent.resolve())
        return rel.as_posix()
    except ValueError:
        return str(html_path)


def set_sidecar_export(
    sidecar: dict[str, Any],
    *,
    theme: Any,
    html_path: Path,
    ir_path: Path,
) -> None:
    """Write sidecar.export = {theme, path}. Archify JSON is not touched."""
    if not isinstance(sidecar, dict):
        return
    sidecar["export"] = {
        "theme": normalize_export_theme(theme),
        "path": path_for_sidecar_export(html_path, ir_path),
    }


def native_save_path(
    initial_dir: str,
    diagram_type: str = "workflow",
    *,
    initial_file: str | None = None,
) -> dict[str, Any]:
    """Native Save dialog. Sibling of native_pick_path. Cancel leaves the buffer unsaved."""
    suffix = save_name_suffix(diagram_type)
    init_literal = json.dumps(initial_dir)
    file_literal = json.dumps(initial_file or f"untitled{suffix}")
    suffix_literal = json.dumps(suffix)
    pattern_literal = json.dumps(f"*{suffix}")
    script = (
        "import sys\n"
        "try:\n"
        "    from tkinter import Tk, filedialog\n"
        "except Exception:\n"
        "    sys.exit(2)\n"
        "root = Tk()\n"
        "root.withdraw()\n"
        "try:\n"
        '    root.attributes("-topmost", True)\n'
        "except Exception:\n"
        "    pass\n"
        "path = filedialog.asksaveasfilename(\n"
        f"    initialdir={init_literal},\n"
        f"    initialfile={file_literal},\n"
        '    title="Save diagram",\n'
        f"    defaultextension={suffix_literal},\n"
        f'    filetypes=[("Archify diagrams", {pattern_literal}), ("All files", "*.*")],\n'
        ")\n"
        'print(path if path else "", end="")\n'
    )
    try:
        proc = subprocess.run(
            [sys.executable, "-c", script],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
    except (OSError, subprocess.SubprocessError):
        return {"ok": False, "error": "native picker unavailable"}
    if proc.returncode != 0:
        return {"ok": False, "error": "native picker unavailable"}
    chosen = (proc.stdout or "").strip()
    if not chosen:
        return {"ok": True, "cancelled": True}
    return {"ok": True, "path": chosen}


