def session_public() -> dict[str, Any]:
    """File plus generation the SPA echoes on mutating calls.

    Caller holds _state_lock, or no request threads exist yet.
    """
    return {
        "file": str(_file_path) if _file_path is not None else None,
        "gen": _session_gen,
    }


def _session_file_text(value: Any) -> tuple[bool, str | None]:
    if value is None or value == "":
        return True, None
    if not isinstance(value, str):
        return False, None
    return True, value


def _files_match(got: str | None, want: str | None) -> bool:
    if got is None and want is None:
        return True
    if got is None or want is None:
        return False
    if got == want:
        return True
    try:
        left = Path(got).resolve()
        right = Path(want).resolve()
    except (OSError, RuntimeError):
        return False
    if left == right:
        return True
    if os.name == "nt":
        return os.path.normcase(str(left)) == os.path.normcase(str(right))
    return False


def session_matches(presented: Any) -> bool:
    """True when this tab still has the diagram the server is editing.

    Caller holds _state_lock. Missing or malformed identity does not match.
    """
    if not isinstance(presented, dict):
        return False
    gen = presented.get("gen")
    if isinstance(gen, bool) or not isinstance(gen, int):
        return False
    if gen != _session_gen:
        return False
    ok, got = _session_file_text(presented.get("file"))
    if not ok:
        return False
    want = str(_file_path) if _file_path is not None else None
    return _files_match(got, want)


def bump_session() -> None:
    """Open, New, template, or Discard reload. Caller holds _state_lock."""
    global _session_gen
    _session_gen += 1


def _addr_in_use(exc: OSError) -> bool:
    # Windows http.server with SO_REUSEADDR reports a busy port as 10013
    # (access denied) instead of 10048. An excluded port is the same code.
    # Either way this port cannot be taken; the scan tries the next one.
    winerror = getattr(exc, "winerror", None)
    if winerror in (10013, 10048):
        return True
    if exc.errno in (errno.EADDRINUSE, 10048):
        return True
    text = str(exc).lower()
    return (
        "address already in use" in text
        or "only one usage of each socket address" in text
        or "access a socket in a way forbidden" in text
    )


def listen_port_candidates(preferred: int) -> list[int]:
    """Preferred port first, then the next ports in 8770..8789."""
    if isinstance(preferred, bool) or not isinstance(preferred, int):
        return []
    if preferred < 0 or preferred > 65535:
        return [preferred]
    if _PORT_WINDOW_LO <= preferred <= _PORT_WINDOW_HI:
        return list(range(preferred, _PORT_WINDOW_HI + 1))
    window = [port for port in range(_PORT_WINDOW_LO, _PORT_WINDOW_HI + 1) if port != preferred]
    return [preferred] + window


class ExclusiveThreadingHTTPServer(ThreadingHTTPServer):
    # Default SO_REUSEADDR on Windows turns a busy port into WinError 10013
    # and can let two listeners share one port. Exclusive bind makes the
    # next bendwright take the next port in the window.
    allow_reuse_address = False


def bind_loopback(preferred: int) -> tuple[ThreadingHTTPServer | None, OSError | None]:
    """Bind the first free candidate. A non-in-use error stops the scan."""
    last_in_use: OSError | None = None
    for port in listen_port_candidates(preferred):
        try:
            return ExclusiveThreadingHTTPServer(("127.0.0.1", port), Handler), None
        except OSError as exc:
            if _addr_in_use(exc):
                last_in_use = exc
                continue
            return None, exc
    return None, last_in_use


def state_payload() -> dict[str, Any]:
    has_doc = isinstance(_doc, dict) and bool(_doc)
    payload: dict[str, Any] = {
        "file": str(_file_path) if _file_path is not None else None,
        "session": session_public(),
        "diagram_type": _diagram_type,
        "doc": _doc if has_doc else None,
        "ir": (
            {k: list(_doc.get(k) or []) for k in ir_collection_keys(_diagram_type)}
            if has_doc
            else {k: [] for k in ir_collection_keys(_diagram_type)}
        ),
        "enums": merge_enums(_doc if has_doc else {}),
        "archify": _archify_path,
        "unsaved_new": _file_path is None and has_doc,
    }
    # Brands stay on GET /api/brands — not in /api/state and not in IR_KEYS.
    payload["archify_patch"] = _archify_patch_state
    # Migration and data-dir notes share the startup status line with the patch note.
    archify_note = _join_notes(
        _archify_version_note, _archify_patch_note, _catalog_note, _data_dir_note
    )
    if archify_note:
        payload["archify_note"] = archify_note
    payload["catalog"] = list(_catalog_marks)
    payload["catalog_ok"] = bool(_catalog_marks)
    payload["dropped_icons"] = dict(_DROPPED_BRAND_CATALOG)
    if _user_icon_note:
        payload["icon_note"] = _user_icon_note
    # M28a: in-memory sidecar. Not part of the workflow JSON.
    payload["sidecar"] = _sidecar
    if _sidecar_note:
        payload["sidecar_note"] = _sidecar_note
    # Editor-only. Export/preview never reads the user type library.
    lib, lib_note = load_type_library()
    payload["type_library"] = lib
    if lib_note:
        payload["type_library_note"] = lib_note
    return payload


def merge_enums(doc: dict[str, Any]) -> dict[str, list[str]]:
    """Static enums merged with distinct in-file values (order: static first)."""
    collected: dict[str, set[str]] = {k: set() for k in STATIC_ENUMS}

    for node in doc.get("nodes") or []:
        if isinstance(node, dict) and isinstance(node.get("type"), str):
            collected["node.type"].add(node["type"])

    for comp in doc.get("components") or []:
        if isinstance(comp, dict) and isinstance(comp.get("type"), str):
            collected["node.type"].add(comp["type"])

    for lane in doc.get("lanes") or []:
        if isinstance(lane, dict) and isinstance(lane.get("variant"), str):
            collected["lane.variant"].add(lane["variant"])

    for edge in doc.get("edges") or []:
        if not isinstance(edge, dict):
            continue
        for key, enum_key in (
            ("role", "edge.role"),
            ("variant", "edge.variant"),
            ("route", "edge.route"),
            ("fromSide", "edge.fromSide"),
            ("toSide", "edge.toSide"),
        ):
            v = edge.get(key)
            if isinstance(v, str):
                collected[enum_key].add(v)

    for conn in doc.get("connections") or []:
        if not isinstance(conn, dict):
            continue
        for key, enum_key in (
            ("variant", "edge.variant"),
            ("route", "connection.route"),
            ("fromSide", "edge.fromSide"),
            ("toSide", "edge.toSide"),
        ):
            v = conn.get(key)
            if isinstance(v, str):
                collected[enum_key].add(v)

    for boundary in doc.get("boundaries") or []:
        if isinstance(boundary, dict) and isinstance(boundary.get("kind"), str):
            collected["boundary.kind"].add(boundary["kind"])

    meta = doc.get("meta")
    if isinstance(meta, dict):
        qp = meta.get("quality_profile")
        if isinstance(qp, str):
            collected["meta.quality_profile"].add(qp)

    cards = doc.get("cards")
    if isinstance(cards, list):
        for card in cards:
            if isinstance(card, dict) and isinstance(card.get("dot"), str):
                collected["cards.dot"].add(card["dot"])

    out: dict[str, list[str]] = {}
    for key, base in STATIC_ENUMS.items():
        merged: list[str] = []
        seen: set[str] = set()
        for v in base:
            if v not in seen:
                merged.append(v)
                seen.add(v)
        for v in sorted(collected[key]):
            if v not in seen:
                merged.append(v)
                seen.add(v)
        out[key] = merged
    return out


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _is_point(value: Any) -> bool:
    return (
        isinstance(value, list)
        and len(value) == 2
        and _is_number(value[0])
        and _is_number(value[1])
    )


def _diagram_kind(doc: dict[str, Any]) -> str:
    dtype = doc.get("diagram_type") if isinstance(doc, dict) else None
    if dtype == "architecture":
        return "architecture"
    return "workflow"


def _element_list(doc: dict[str, Any]) -> list[Any]:
    key = "components" if _diagram_kind(doc) == "architecture" else "nodes"
    items = doc.get(key)
    return items if isinstance(items, list) else []


def _relation_list(doc: dict[str, Any]) -> list[Any]:
    key = "connections" if _diagram_kind(doc) == "architecture" else "edges"
    items = doc.get(key)
    return items if isinstance(items, list) else []


def _structural_workflow(doc: dict[str, Any]) -> list[str]:
    errors: list[str] = []

    meta = doc.get("meta")
    if not isinstance(meta, dict):
        errors.append("meta must be an object")
    elif "title" not in meta:
        errors.append("meta.title is required")

    nodes = doc.get("nodes")
    edges = doc.get("edges")
    lanes = doc.get("lanes")
    if not isinstance(nodes, list):
        errors.append("nodes must be an array")
        nodes = []
    if not isinstance(edges, list):
        errors.append("edges must be an array")
        edges = []
    if not isinstance(lanes, list):
        errors.append("lanes must be an array")
        lanes = []

    lane_ids: list[str] = []
    for i, lane in enumerate(lanes):
        if not isinstance(lane, dict):
            errors.append(f"lanes[{i}] must be an object")
            continue
        for req in ("id", "label"):
            if req not in lane:
                errors.append(f"lanes[{i}].{req} is required")
        lid = lane.get("id")
        if isinstance(lid, str):
            if not ID_RE.match(lid):
                errors.append(f"lanes[{i}].id invalid: {lid!r}")
            lane_ids.append(lid)
        elif "id" in lane:
            errors.append(f"lanes[{i}].id must be a string")

    if len(lane_ids) != len(set(lane_ids)):
        errors.append("lane ids must be unique")
    lane_set = set(lane_ids)

    node_ids: list[str] = []
    for i, node in enumerate(nodes):
        if not isinstance(node, dict):
            errors.append(f"nodes[{i}] must be an object")
            continue
        for req in ("id", "lane", "col", "type", "label"):
            if req not in node:
                errors.append(f"nodes[{i}].{req} is required")
        nid = node.get("id")
        if isinstance(nid, str):
            if not ID_RE.match(nid):
                errors.append(f"nodes[{i}].id invalid: {nid!r}")
            node_ids.append(nid)
        elif "id" in node:
            errors.append(f"nodes[{i}].id must be a string")

        nlane = node.get("lane")
        if isinstance(nlane, str) and nlane not in lane_set:
            errors.append(f"nodes[{i}].lane references missing lane: {nlane!r}")

        col = node.get("col")
        if "col" in node and (isinstance(col, bool) or not isinstance(col, int)):
            errors.append(f"nodes[{i}].col must be an integer")

    if len(node_ids) != len(set(node_ids)):
        errors.append("node ids must be unique")
    node_set = set(node_ids)

    for i, edge in enumerate(edges):
        if not isinstance(edge, dict):
            errors.append(f"edges[{i}] must be an object")
            continue
        for req in ("from", "to"):
            if req not in edge:
                errors.append(f"edges[{i}].{req} is required")
        fr = edge.get("from")
        to = edge.get("to")
        if isinstance(fr, str) and fr not in node_set:
            errors.append(f"edges[{i}].from references missing node: {fr!r}")
        if isinstance(to, str) and to not in node_set:
            errors.append(f"edges[{i}].to references missing node: {to!r}")

    return errors


def _structural_architecture(doc: dict[str, Any]) -> list[str]:
    """Required shape only. Archify reports measure and schema details."""
    errors: list[str] = []
    if doc.get("schema_version") != 1:
        errors.append("schema_version must be 1")

    meta = doc.get("meta")
    if not isinstance(meta, dict):
        errors.append("meta must be an object")
    elif not isinstance(meta.get("title"), str) or not str(meta.get("title")).strip():
        errors.append("meta.title is required")

    components = doc.get("components")
    if not isinstance(components, list):
        errors.append("components must be an array")
        components = []
    elif len(components) < 1:
        errors.append("components must contain at least 1")

    comp_ids: list[str] = []
    for i, comp in enumerate(components):
        if not isinstance(comp, dict):
            errors.append(f"components[{i}] must be an object")
            continue
        for req in ("id", "type", "label"):
            if req not in comp:
                errors.append(f"components[{i}].{req} is required")
        cid = comp.get("id")
        if isinstance(cid, str):
            if not ID_RE.match(cid):
                errors.append(f"components[{i}].id invalid: {cid!r}")
            comp_ids.append(cid)
        elif "id" in comp:
            errors.append(f"components[{i}].id must be a string")
        if "pos" in comp and not _is_point(comp.get("pos")):
            errors.append(f"components[{i}].pos must be [x, y]")
        size = comp.get("size")
        if "size" in comp and not (
            _is_point(size) and size[0] > 0 and size[1] > 0
        ):
            errors.append(f"components[{i}].size must be [w, h] with positive numbers")
        for key in ("row", "col"):
            val = comp.get(key)
            if key in comp and (isinstance(val, bool) or not isinstance(val, int) or val < 0):
                errors.append(f"components[{i}].{key} must be an integer >= 0")

    if len(comp_ids) != len(set(comp_ids)):
        errors.append("component ids must be unique")
    comp_set = set(comp_ids)

    if "connections" in doc and not isinstance(doc.get("connections"), list):
        errors.append("connections must be an array")
    connections = doc.get("connections") if isinstance(doc.get("connections"), list) else []
    for i, conn in enumerate(connections):
        if not isinstance(conn, dict):
            errors.append(f"connections[{i}] must be an object")
            continue
        for req in ("from", "to"):
            if req not in conn:
                errors.append(f"connections[{i}].{req} is required")
        fr = conn.get("from")
        to = conn.get("to")
        if isinstance(fr, str) and fr not in comp_set:
            errors.append(f"connections[{i}].from references missing component: {fr!r}")
        if isinstance(to, str) and to not in comp_set:
            errors.append(f"connections[{i}].to references missing component: {to!r}")
        eid = conn.get("id")
        if "id" in conn and not isinstance(eid, str):
            errors.append(f"connections[{i}].id must be a string")
        elif isinstance(eid, str) and eid and not ID_RE.match(eid):
            errors.append(f"connections[{i}].id invalid: {eid!r}")

    if "boundaries" in doc and not isinstance(doc.get("boundaries"), list):
        errors.append("boundaries must be an array")
    boundaries = doc.get("boundaries") if isinstance(doc.get("boundaries"), list) else []
    for i, boundary in enumerate(boundaries):
        if not isinstance(boundary, dict):
            errors.append(f"boundaries[{i}] must be an object")
            continue
        for req in ("kind", "label", "wraps"):
            if req not in boundary:
                errors.append(f"boundaries[{i}].{req} is required")
        kind = boundary.get("kind")
        if "kind" in boundary and kind not in ("region", "security-group"):
            errors.append(f"boundaries[{i}].kind must be region or security-group")
        wraps = boundary.get("wraps")
        if "wraps" in boundary and (
            not isinstance(wraps, list) or len(wraps) < 1
        ):
            errors.append(f"boundaries[{i}].wraps must list at least one component")
        elif isinstance(wraps, list):
            for wid in wraps:
                if not isinstance(wid, str) or wid not in comp_set:
                    errors.append(
                        f"boundaries[{i}].wraps references missing component: {wid!r}"
                    )
        pad = boundary.get("pad")
        if "pad" in boundary and (not _is_number(pad) or pad < 0):
            errors.append(f"boundaries[{i}].pad must be a number >= 0")

    return errors


def _remember_absent_empty_keys(doc: dict[str, Any] | None) -> None:
    """Record optional collections the loaded document did not contain.

    Caller holds _state_lock, or no request threads exist yet.
    """
    global _absent_empty_keys
    if not isinstance(doc, dict):
        _absent_empty_keys = set()
        return
    _absent_empty_keys = {key for key in OPTIONAL_EMPTY_KEYS if key not in doc}


def _copy_absent_empty_keys() -> set[str]:
    with _state_lock:
        return set(_absent_empty_keys)


def _strip_absent_empty_collections(doc: dict[str, Any], absent: set[str]) -> None:
    """Drop empty optional collections that were not in the loaded document.

    The SPA keeps [] in memory so the forms still render. Write only.
    """
    for key in absent:
        value = doc.get(key)
        if isinstance(value, list) and len(value) == 0:
            doc.pop(key, None)


def _prepare_write_doc(doc: dict[str, Any]) -> None:
    _strip_absent_empty_collections(doc, _copy_absent_empty_keys())


def structural_check(doc: dict[str, Any]) -> list[str]:
    if not isinstance(doc, dict):
        return ["IR root must be an object"]
    dtype = doc.get("diagram_type")
    if dtype == "architecture":
        return _structural_architecture(doc)
    if isinstance(dtype, str) and dtype not in ("workflow",):
        shown = dtype if dtype.strip() else "(empty)"
        return [
            f"{shown} diagrams are not supported yet - workflow or architecture only"
        ]
    return _structural_workflow(doc)


def atomic_write(path: Path, doc: dict[str, Any], trailing_newline: bool) -> None:
    text = json.dumps(doc, indent=2, ensure_ascii=False)
    if trailing_newline:
        if not text.endswith("\n"):
            text += "\n"
    else:
        text = text.rstrip("\n")

    parent = path.parent
    fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=str(parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_name, path)
    except Exception:
        try:
            os.unlink(tmp_name)
        except OSError:
            pass
        raise


def _write_system_temp_json(doc: dict[str, Any], trailing_newline: bool) -> str:
    """Write candidate IR to a system-temp file; caller must delete."""
    text = json.dumps(doc, indent=2, ensure_ascii=False)
    if trailing_newline:
        if not text.endswith("\n"):
            text += "\n"
    else:
        text = text.rstrip("\n")
    fd, tmp_name = tempfile.mkstemp(prefix=f"{APP}-cand-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
            f.flush()
    except Exception:
        try:
            os.unlink(tmp_name)
        except OSError:
            pass
        raise
    return tmp_name


def _archify_temp_json(
    doc: dict[str, Any],
    trailing_newline: bool,
    sidecar: dict[str, Any] | None = None,
) -> tuple[str, list[str]]:
    """System-temp IR with our brand URLs rewritten. Caller must delete.

    The doc argument is not mutated. atomic_write never uses this copy.
    A loopback URL for a dropped icon becomes the catalog id on this copy only.
    A loopback URL for a missing icon is omitted on this copy only.
    Returns (temp path, missing icon names).
    """
    rewritten, missing = _rewrite_brands_for_archify(doc, sidecar)
    return _write_system_temp_json(rewritten, trailing_newline), missing


def _unlink_quiet(path: str | Path) -> None:
    try:
        os.unlink(path)
    except OSError:
        pass


def _read_saved_doc(path: Path) -> tuple[dict[str, Any], bool] | None:
    """Read a saved IR without SystemExit. None if it cannot be parsed."""
    try:
        raw = path.read_text(encoding="utf-8")
        doc = json.loads(raw)
    except (OSError, UnicodeError, json.JSONDecodeError):
        return None
    if not isinstance(doc, dict):
        return None
    return doc, raw.endswith("\n")


# M27-fix: archify brand markup. One block so a rename is a one-place fix.
# mark_attrs are the visible icon name; source_attrs must not keep a loopback URL.
_BRAND_MARKUP: dict[str, Any] = {
    "group_tag": "g",
    "node_id_attr": "data-node-id",
    "mark_attrs": (
        "data-brand-mark",
        "data-brand-title",
        "data-node-brand",
        "data-node-brand-id",
    ),
    "source_attrs": (
        "data-brand-source",
        "data-node-brand-source",
    ),
    "title_tag": "title",
    "aria_attr": "aria-label",
}


def _join_notes(*notes: str | None) -> str | None:
    parts = [n.strip() for n in notes if isinstance(n, str) and n.strip()]
    return " ".join(parts) if parts else None


def _brand_miss_note(count: int) -> str:
    return f"archify markup changed; brand names not applied to {count} nodes"


def _our_branded_nodes(
    doc: dict[str, Any], sidecar: dict[str, Any] | None = None
) -> list[dict[str, str]]:
    """Nodes or components whose brand URL is a gap, user, or sidecar icon."""
    elements = _element_list(doc)
    if not elements:
        return []
    found: list[dict[str, str]] = []
    for node in elements:
        if not isinstance(node, dict):
            continue
        brand = node.get("brand")
        if not isinstance(brand, dict):
            continue
        url = brand.get("url")
        if not isinstance(url, str):
            continue
        match = _OUR_BRAND_URL_RE.match(url)
        if not match:
            continue
        name = match.group(1)
        icon = _icon_asset(name, sidecar)
        if icon is None:
            continue
        node_id = node.get("id")
        host = urlparse(url).hostname or ""
        found.append(
            {
                "id": node_id if isinstance(node_id, str) else "",
                "name": name,
                "label": str(icon["label"]),
                "host": host,
            }
        )
    return found


def _find_node_group(html: str, node_id: str) -> tuple[int, int] | None:
    """Span of <g data-node-id="...">...</g>, including nested groups."""
    if not node_id:
        return None
    tag = str(_BRAND_MARKUP["group_tag"])
    attr = str(_BRAND_MARKUP["node_id_attr"])
    open_re = re.compile(
        rf'<{tag}\b(?=[^>]*\b{re.escape(attr)}="{re.escape(node_id)}")[^>]*>',
        re.IGNORECASE,
    )
    token_re = re.compile(rf"</{tag}>|<{tag}\b", re.IGNORECASE)
    match = open_re.search(html)
    if not match:
        return None
    pos = match.end()
    depth = 1
    end: int | None = None
    while pos < len(html):
        token = token_re.search(html, pos)
        if not token:
            return None
        if token.group(0).startswith("</"):
            depth -= 1
            if depth == 0:
                end = token.end()
                break
        else:
            depth += 1
        pos = token.end()
    if end is None:
        return None
    return match.start(), end


def _set_attr_values(chunk: str, attr: str, value: str) -> tuple[str, bool]:
    pattern = re.compile(rf'(\b{re.escape(attr)}=")([^"]*)(")')
    found = False
    safe = html_escape(value, quote=True)

    def repl(m: re.Match[str]) -> str:
        nonlocal found
        found = True
        return m.group(1) + safe + m.group(3)

    return pattern.sub(repl, chunk), found


def _replace_attr_token(chunk: str, attr: str, token: str, label: str) -> tuple[str, bool]:
    if not token:
        return chunk, False
    pattern = re.compile(rf'(\b{re.escape(attr)}=")([^"]*)(")')
    found = False
    safe = html_escape(label, quote=True)

    def repl(m: re.Match[str]) -> str:
        nonlocal found
        val = m.group(2)
        if token not in val:
            return m.group(0)
        found = True
        return m.group(1) + val.replace(token, safe) + m.group(3)

    return pattern.sub(repl, chunk), found


def _replace_title_token(chunk: str, token: str, label: str) -> tuple[str, bool]:
    if not token:
        return chunk, False
    tag = str(_BRAND_MARKUP["title_tag"])
    pattern = re.compile(
        rf"(<{tag}\b[^>]*>)(.*?)(</{tag}>)",
        re.IGNORECASE | re.DOTALL,
    )
    found = False
    safe = html_escape(label, quote=False)

    def repl(m: re.Match[str]) -> str:
        nonlocal found
        body = m.group(2)
        if token not in body:
            return m.group(0)
        found = True
        return m.group(1) + body.replace(token, safe) + m.group(3)

    return pattern.sub(repl, chunk), found


def _rewrite_brand_group(chunk: str, name: str, label: str, host: str) -> tuple[str, bool]:
    """Rename our brand inside one node group. Returns (chunk, mark_hook_found)."""
    mark_attrs = _BRAND_MARKUP["mark_attrs"]
    source_attrs = _BRAND_MARKUP["source_attrs"]
    if not isinstance(mark_attrs, tuple) or not isinstance(source_attrs, tuple) or not mark_attrs:
        return chunk, False
    for attr in mark_attrs:
        chunk, _found = _set_attr_values(chunk, str(attr), label)
    source = f"bendwright:{name}"
    for attr in source_attrs:
        chunk, _found = _set_attr_values(chunk, str(attr), source)
    chunk, _found = _replace_attr_token(chunk, str(_BRAND_MARKUP["aria_attr"]), host, label)
    chunk, _found = _replace_title_token(chunk, host, label)
    mark_attr = str(mark_attrs[0])
    matched = re.search(rf'\b{re.escape(mark_attr)}="', chunk) is not None
    return chunk, matched


def _apply_brand_display_names(
    html: bytes, ir_path: Path, sidecar: dict[str, Any] | None = None
) -> tuple[bytes, str | None]:
    """Replace the loopback hostname for our brands. Never fails the deliver.

    Foreign object brands are not rewritten. data-brand-sha256 and inlined
    data:image/png bytes are left untouched.
    """
    loaded = _read_saved_doc(ir_path)
    if loaded is None:
        return html, None
    targets = _our_branded_nodes(loaded[0], sidecar)
    if not targets:
        return html, None
    try:
        text = html.decode("utf-8")
    except UnicodeError:
        return html, _brand_miss_note(len(targets))
    missed = 0
    for target in targets:
        span = _find_node_group(text, target["id"])
        if span is None:
            missed += 1
            continue
        start, end = span
        chunk, matched = _rewrite_brand_group(
            text[start:end], target["name"], target["label"], target["host"]
        )
        if not matched:
            missed += 1
            continue
        text = text[:start] + chunk + text[end:]
    out = text.encode("utf-8")
    if missed:
        return out, _brand_miss_note(missed)
    return out, None


# M28a: paint overlay. Selectors, attrs, and marker ids live in this block
# (brand hooks stay in _BRAND_MARKUP). Do not scatter these strings.
#
# Edge style key: edge.id when it is a non-empty string. Otherwise
# "{from}->{to}#{n}" where n counts earlier edges with the same from and to
# that also have no id. Reordering an unrelated edge does not change n.
# Sidecar file: same stem as the exported HTML
# (name.workflow.json -> name.bendwright.json), beside the IR.
#
# Edge match never uses data-edge-key. That attribute is archify's render
# order, not the IR index. Both the CSS selector and the marker pass use:
#   1. data-edge-from + data-edge-to
#   2. data-edge-id when the IR edge has an id
#   3. otherwise skip paths that have data-edge-id. If several id-less
#      edges share from/to, require data-edge-label when that label is
#      unique among them (a missing label matches a path with no
#      data-edge-label).
#   4. If several id-less edges still share from/to and label, pair DOM
#      order of those paths with IR order in that bucket (the sidecar #n
#      count, narrowed to one label). An attribute selector cannot name
#      only the nth path, so paint is applied only when every edge in the
#      bucket has the same color and dash. Otherwise each of those edges
#      is a markup miss and is not painted.
# Arrowheads: one <marker> per used color per theme, id
# bw-arrow-<color>-<dark|light>, explicit polygon fill. Theme CSS points
# marker-end at the matching marker. No !important.
_OVERLAY_MARKUP: dict[str, Any] = {
    "edge_tag": "path",
    "edge_from_attr": "data-edge-from",
    "edge_to_attr": "data-edge-to",
    "edge_id_attr": "data-edge-id",
    "edge_key_attr": "data-edge-key",
    "edge_label_attr": "data-edge-label",
    "edge_label_tag": "g",
    "marker_end_attr": "marker-end",
    "marker_tag": "marker",
    "marker_shape_tag": "polygon",
    "marker_points": "0 0, 10 3.5, 0 7",
    "marker_width": "10",
    "marker_height": "7",
    "marker_ref_x": "9",
    "marker_ref_y": "3.5",
    "marker_orient": "auto",
    "stock_marker_ids": (
        "arrowhead",
        "arrowhead-emphasis",
        "arrowhead-security",
        "arrowhead-dashed",
    ),
    "defs_tag": "defs",
    "node_group_tag": "g",
    "node_id_attr": "data-node-id",
    "node_box_tag": "rect",
    "node_box_nth": 2,
    "style_tag": "style",
    "theme_attr": "data-theme",
    "theme_dark": "dark",
    "theme_light": "light",
    "legend_tag": "aside",
    "legend_id": "bw-style-legend",
    "style_id": "bw-style-overlay",
    # Custom type name is post-process only. Never rewrite data-node-kind.
    "node_kind_attr": "data-node-kind",
    "node_kind_label_attr": "data-node-kind-label",
    "node_aria_attr": "aria-label",
    "node_title_tag": "title",
}

