_HELP_PAGE_TAIL = """</main>\n</body>\n</html>\n"""


def help_page_html() -> str:
    """Offline /help page. The guide fragment is embedded verbatim."""
    return _HELP_PAGE_HEAD + _HELP_BODY + _HELP_PAGE_TAIL


class Handler(BaseHTTPRequestHandler):
    server_version = f"{APP}/1"

    def log_message(self, fmt: str, *args: Any) -> None:
        sys.stderr.write(f"[{APP}] " + (fmt % args) + "\n")

    def _send(self, code: int, body: bytes, content_type: str) -> None:
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def _send_json(self, code: int, obj: Any) -> None:
        data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self._send(code, data, "application/json; charset=utf-8")

    def _read_json_body(self) -> tuple[Any | None, str | None]:
        length = int(self.headers.get("Content-Length") or "0")
        raw = self.rfile.read(length) if length else b""
        try:
            return json.loads(raw.decode("utf-8")), None
        except (UnicodeDecodeError, json.JSONDecodeError) as e:
            return None, f"invalid JSON body: {e}"

    def _presented_session(self) -> Any:
        """Session identity from the SPA, or None when it is missing or unreadable."""
        raw = self.headers.get(_SESSION_HEADER)
        if raw is None or str(raw).strip() == "":
            return None
        try:
            blob = base64.b64decode(str(raw).strip(), validate=False)
            parsed = json.loads(blob.decode("utf-8"))
        except (ValueError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
            return None
        return parsed

    def _send_stale(self) -> None:
        self._send_json(
            409,
            {
                "ok": False,
                "saved": False,
                "stale": True,
                "error": STALE_TAB_MSG,
                "errors": [STALE_TAB_MSG],
            },
        )

    def _session_is_current(self, presented: Any) -> bool:
        with _state_lock:
            return session_matches(presented)

    def _handle_alive(self) -> None:
        """SSE presence. Held open while the tab exists; not an inflight request."""
        global _alive, _alive_seen, _last_zero_ts
        self.close_connection = True
        try:
            self.connection.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except OSError:
            pass
        try:
            self.send_response(200)
            self.send_header("Content-Type", "text/event-stream")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Connection", "close")
            self.end_headers()
        except (
            BrokenPipeError,
            ConnectionResetError,
            ConnectionAbortedError,
            TimeoutError,
            OSError,
        ):
            return
        with _alive_lock:
            _alive += 1
            _alive_seen = True
        try:
            # Comment first so EventSource opens before the first sleep. No retry: field.
            while True:
                self.wfile.write(b":\n\n")
                self.wfile.flush()
                time.sleep(ALIVE_KEEPALIVE_S)
        except (
            BrokenPipeError,
            ConnectionResetError,
            ConnectionAbortedError,
            TimeoutError,
            OSError,
        ):
            return
        finally:
            with _alive_lock:
                _alive -= 1
                if _alive == 0:
                    _last_zero_ts = time.monotonic()

    def do_GET(self) -> None:  # noqa: N802
        path = urlparse(self.path).path
        if path == "/api/alive":
            self._handle_alive()
            return
        _begin_request()
        try:
            if path == "/":
                html = SPA_HTML.encode("utf-8")
                self._send(200, html, "text/html; charset=utf-8")
                return
            if path == "/help":
                self._send(200, help_page_html().encode("utf-8"), "text/html; charset=utf-8")
                return
            if path in ("/favicon.svg", "/favicon.ico"):
                # .ico would 404. Same mark as SVG so the tab icon still resolves.
                self._send(200, _FAVICON_SVG, "image/svg+xml")
                return
            if path == "/preview":
                with _state_lock:
                    body = _preview_html
                if body is None:
                    self._send_json(
                        200,
                        {
                            "ok": False,
                            "error": "no preview available (archify absent or deliver not yet run)",
                        },
                    )
                    return
                self._send(200, body, "text/html; charset=utf-8")
                return
            if path == "/api/diagram":
                with _state_lock:
                    body = _diagram_html
                    archify = _archify_path
                if archify is None:
                    self._send_json(404, {"archify": False})
                    return
                if body is None:
                    self._send_json(
                        404,
                        {"ok": False, "error": "no diagram fragment (deliver not yet run)"},
                    )
                    return
                self._send(200, body, "text/html; charset=utf-8")
                return
            if path == "/api/layout":
                # Layout from in-memory _doc (may differ from disk until Save).
                with _state_lock:
                    archify = _archify_path
                    dtype = _diagram_type
                    doc = _doc
                    trailing = _had_trailing_newline
                    sidecar = copy.deepcopy(_sidecar)
                    evidence_dir = _file_path.parent if _file_path is not None else None
                if archify is None or not isinstance(doc, dict) or not doc:
                    self._send_json(404, {"archify": False})
                    return
                dtype = resolve_diagram_type(doc, dtype)
                tmp_name, _missing = _archify_temp_json(doc, trailing, sidecar)
                try:
                    layout, err = fetch_layout(
                        archify, dtype, Path(tmp_name), sidecar, evidence_dir
                    )
                finally:
                    _unlink_quiet(tmp_name)
                if layout is None:
                    self._send_json(
                        200,
                        {"ok": False, "error": err or "layout-json failed"},
                    )
                    return
                self._send_json(200, layout)
                return
            brand_match = _BRAND_PATH_RE.match(path)
            if brand_match:
                with _state_lock:
                    sidecar = copy.deepcopy(_sidecar)
                icon = _icon_asset(brand_match.group(1), sidecar)
                if icon is None or not isinstance(icon.get("png"), (bytes, bytearray)):
                    self._send(404, b"unknown brand", "text/plain; charset=utf-8")
                    return
                self._send(200, bytes(icon["png"]), "image/png")
                return
            if path == "/api/brands":
                self._send_json(200, brands_api_payload())
                return
            if path == "/api/catalog":
                self._send_json(200, catalog_api_payload())
                return
            if path == "/api/type-library":
                lib, note = load_type_library()
                payload: dict[str, Any] = {"ok": True, "library": lib}
                if note:
                    payload["note"] = note
                self._send_json(200, payload)
                return
            if path == "/api/state":
                with _state_lock:
                    payload = state_payload()
                self._send_json(200, payload)
                return
            self._send_json(404, {"ok": False, "error": "not found"})
        finally:
            _end_request()

    def do_POST(self) -> None:  # noqa: N802
        global _doc, _file_path, _diagram_type, _had_trailing_newline, _sidecar_unreadable
        _begin_request()
        try:
            path = urlparse(self.path).path
            if path == "/api/pick":
                self._handle_pick()
                return
            if path == "/api/new":
                self._handle_new()
                return
            if path == "/api/brands/rescan":
                self._handle_brand_rescan()
                return
            if path == "/api/open":
                self._handle_open()
                return
            if path == "/api/preview":
                self._handle_preview()
                return
            if path == "/api/export":
                self._handle_export()
                return
            if path == "/api/type-library":
                self._handle_type_library_save()
                return
            if path != "/api/save":
                self._send_json(404, {"ok": False, "error": "not found"})
                return

            body, err = self._read_json_body()
            presented = self._presented_session()
            if not self._session_is_current(presented):
                self._send_stale()
                return
            if err is not None:
                self._send_json(
                    200,
                    {"ok": False, "saved": False, "errors": [err]},
                )
                return

            if not isinstance(body, dict):
                self._send_json(
                    200,
                    {"ok": False, "saved": False, "errors": ["body must be a JSON object"]},
                )
                return
            candidate, sidecar_in, split_err = _split_edit_body(body)
            if split_err:
                self._send_json(
                    200, {"ok": False, "saved": False, "errors": [split_err]}
                )
                return
            _prepare_write_doc(candidate)

            errors = structural_check(candidate)
            if errors:
                self._send_json(200, {"ok": False, "saved": False, "errors": errors})
                return

            with _state_lock:
                archify = _archify_path
                trailing = _had_trailing_newline
                dtype = resolve_diagram_type(candidate, _diagram_type)
                current_path = _file_path

            adopting = False
            target = current_path
            path_raw = body.get("path")
            # Path from the Save dialog: first save, Save As, or same-path save.
            if current_path is None or (isinstance(path_raw, str) and path_raw.strip()):
                base_dir = current_path.parent if current_path is not None else Path.cwd()
                chosen, path_err = _diagram_save_path(
                    path_raw if isinstance(path_raw, str) else None,
                    dtype,
                    base_dir=base_dir,
                )
                if chosen is None:
                    self._send_json(
                        200,
                        {
                            "ok": False,
                            "saved": False,
                            "errors": [path_err or "no file open"],
                        },
                    )
                    return
                same_as_current = (
                    current_path is not None
                    and chosen.resolve() == current_path.resolve()
                )
                if not same_as_current:
                    if chosen.is_file() and body.get("replace") is not True:
                        self._send_json(
                            200,
                            {
                                "ok": False,
                                "saved": False,
                                "exists": True,
                                "file": str(chosen),
                                "errors": [f"Replace {chosen.name}?"],
                            },
                        )
                        return
                    adopting = True
                    trailing = True
                target = chosen
                if adopting or current_path is None:
                    inferred = candidate.get("diagram_type")
                    if isinstance(inferred, str) and inferred.strip():
                        dtype = resolve_diagram_type(candidate, dtype)

            if target is None:
                self._send_json(
                    200,
                    {"ok": False, "saved": False, "errors": ["path is required"]},
                )
                return

            evidence_dir = target.parent
            if archify:
                ok_v, v_errors = validate_candidate(
                    archify, dtype, candidate, trailing, evidence_dir
                )
                if not ok_v:
                    self._send_json(200, {"ok": False, "saved": False, "errors": v_errors})
                    return

            saved_session: dict[str, Any] | None = None
            with _state_lock:
                # Re-check under the lock so a tab that lost the race does not write.
                if not session_matches(presented):
                    self._send_stale()
                    return
                if not adopting and _file_path is None:
                    self._send_json(
                        200,
                        {"ok": False, "saved": False, "errors": ["no file open"]},
                    )
                    return
                on_disk = _read_saved_doc(target)
                ir_same = on_disk is not None and on_disk[0] == candidate
                # Style-only save must not rewrite the workflow JSON.
                if not ir_same:
                    try:
                        atomic_write(target, candidate, trailing)
                    except OSError as e:
                        self._send_json(
                            200,
                            {"ok": False, "saved": False, "errors": [f"write failed: {e}"]},
                        )
                        return
                if adopting:
                    # Path changes; generation does not. The saving tab adopts it.
                    _file_path = target
                    _had_trailing_newline = True
                    _sidecar_unreadable = False
                _diagram_type = dtype
                _doc = candidate
                if sidecar_in is not None:
                    sc = copy.deepcopy(sidecar_in)
                else:
                    sc = copy.deepcopy(_sidecar)
                _remember_sidecar(candidate, sc)
                unreadable = _sidecar_unreadable
                saved_session = session_public()

            sc_note = write_sidecar_for(target, sc, unreadable=unreadable, doc=candidate)
            sc_blocked = bool(sc_note) and (
                str(sc_note).startswith("sidecar write failed")
                or "not overwritten" in str(sc_note)
            )
            if sc_blocked and ir_same:
                blocked: dict[str, Any] = {
                    "ok": False,
                    "saved": False,
                    "errors": [sc_note],
                }
                if saved_session is not None:
                    blocked["session"] = saved_session
                self._send_json(200, blocked)
                return

            receipt: dict[str, Any] = {
                "ok": True,
                "saved": True,
                "structural": True,
                "file": str(target),
            }
            if saved_session is not None:
                receipt["session"] = saved_session
            if archify:
                # Render the just-saved file via a rewritten temp. atomic_write
                # above kept the loopback URLs the user authored.
                rendered = deliver_saved_file(archify, dtype, target, None, sc)
                html, note = rendered if isinstance(rendered, tuple) else (None, "preview failed")
                with _state_lock:
                    if html is not None:
                        set_preview_html(html)
                note = _join_notes(sc_note, note)
                if note:
                    receipt["note"] = note
                else:
                    receipt["preview"] = True
            elif sc_note:
                receipt["note"] = sc_note

            self._send_json(200, receipt)
        finally:
            _end_request()

    def _handle_export(self) -> None:
        """Save current JSON, then write HTML to the chosen path (theme from body/sidecar)."""
        global _doc, _diagram_type, _sidecar

        # Read the body before any refusal so a keep-alive connection stays aligned.
        length = int(self.headers.get("Content-Length") or "0")
        raw = self.rfile.read(length) if length else b""
        presented = self._presented_session()
        if not self._session_is_current(presented):
            self._send_stale()
            return

        with _state_lock:
            if not session_matches(presented):
                self._send_stale()
                return
            if _file_path is None:
                self._send_json(200, {"ok": False, "errors": ["no file open"]})
                return
            if _archify_path is None:
                self._send_json(
                    200,
                    {
                        "ok": False,
                        "errors": ["archify not available; cannot render HTML"],
                    },
                )
                return
            archify = _archify_path
            trailing = _had_trailing_newline
            dtype = _diagram_type
            target = _file_path
            evidence_dir = target.parent
            sc = copy.deepcopy(_sidecar)

        body: dict[str, Any] = {}
        stripped = raw.strip()
        if stripped and stripped != b"{}":
            try:
                parsed = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as e:
                self._send_json(
                    200, {"ok": False, "errors": [f"invalid JSON body: {e}"]}
                )
                return
            if not isinstance(parsed, dict):
                self._send_json(
                    200, {"ok": False, "errors": ["body must be a JSON object"]}
                )
                return
            body = parsed

        export_theme = normalize_export_theme(body.get("theme"))
        path_raw = body.get("path")
        if not isinstance(path_raw, str) or not path_raw.strip():
            path_raw = str(export_html_path(target))
        out_path, path_err = _export_html_save_path(path_raw, base_dir=target.parent)
        if out_path is None:
            self._send_json(200, {"ok": False, "errors": [path_err or "bad path"]})
            return
        if out_path.is_file() and body.get("replace") is not True:
            self._send_json(
                200,
                {
                    "ok": False,
                    "exists": True,
                    "file": str(out_path),
                    "errors": [f"Replace {out_path.name}?"],
                },
            )
            return

        sc_note: str | None = None
        # Export always saves the JSON first when the client sends doc (dialog path).
        if isinstance(body.get("doc"), dict):
            # Ensure _split_edit_body sees a sidecar key when only doc was sent.
            if "sidecar" not in body:
                body = dict(body)
                body["sidecar"] = sc
            candidate, sidecar_in, split_err = _split_edit_body(body)
            if split_err:
                self._send_json(200, {"ok": False, "errors": [split_err]})
                return
            _prepare_write_doc(candidate)
            errors = structural_check(candidate)
            if errors:
                self._send_json(200, {"ok": False, "errors": errors})
                return
            dtype = resolve_diagram_type(candidate, dtype)
            ok_v, v_errors = validate_candidate(
                archify, dtype, candidate, trailing, evidence_dir
            )
            if not ok_v:
                self._send_json(200, {"ok": False, "errors": v_errors})
                return
            with _state_lock:
                if not session_matches(presented) or _file_path != target:
                    self._send_stale()
                    return
                on_disk = _read_saved_doc(target)
                ir_same = on_disk is not None and on_disk[0] == candidate
                if not ir_same:
                    try:
                        atomic_write(target, candidate, trailing)
                    except OSError as e:
                        self._send_json(
                            200, {"ok": False, "errors": [f"write failed: {e}"]}
                        )
                        return
                _diagram_type = dtype
                _doc = candidate
                if sidecar_in is not None:
                    sc = copy.deepcopy(sidecar_in)
                else:
                    sc = copy.deepcopy(_sidecar)
                set_sidecar_export(
                    sc, theme=export_theme, html_path=out_path, ir_path=target
                )
                _remember_sidecar(candidate, sc)
                unreadable = _sidecar_unreadable
            sc_note = write_sidecar_for(
                target, sc, unreadable=unreadable, doc=candidate
            )
            sc_blocked = bool(sc_note) and (
                str(sc_note).startswith("sidecar write failed")
                or "not overwritten" in str(sc_note)
            )
            if sc_blocked and ir_same:
                self._send_json(200, {"ok": False, "errors": [sc_note]})
                return
        else:
            # No doc in body: persist theme/path, leave IR on disk as-is.
            set_sidecar_export(
                sc, theme=export_theme, html_path=out_path, ir_path=target
            )
            with _state_lock:
                if not session_matches(presented) or _file_path != target:
                    self._send_stale()
                    return
                doc_for_sc = _doc if isinstance(_doc, dict) else None
                if doc_for_sc is not None:
                    _remember_sidecar(doc_for_sc, sc)
                else:
                    _sidecar = copy.deepcopy(sc)
                unreadable = _sidecar_unreadable
            sc_note = write_sidecar_for(
                target, sc, unreadable=unreadable, doc=doc_for_sc
            )

        with _state_lock:
            if not session_matches(presented) or _file_path != target:
                self._send_stale()
                return
        # Lock OFF during deliver (same as save/preview). Render a rewritten
        # temp so loopback brand URLs resolve; the saved JSON is not rewritten.
        receipt = deliver_saved_file(archify, dtype, target, out_path, sc)
        if not isinstance(receipt, dict):
            receipt = {"ok": False, "errors": ["export failed"]}
        elif receipt.get("ok"):
            # Keep /preview in sync with the exported theme.
            preview = deliver_saved_file(archify, dtype, target, None, sc)
            if isinstance(preview, tuple) and preview[0] is not None:
                with _state_lock:
                    set_preview_html(preview[0])
            if sc_note:
                receipt["note"] = _join_notes(
                    sc_note,
                    receipt.get("note") if isinstance(receipt.get("note"), str) else None,
                )
        self._send_json(200, receipt)

    def _handle_preview(self) -> None:
        """Validate + deliver from a temp candidate; never write the real file (M13).

        An unsaved new diagram has no path. The in-memory doc is enough.
        """
        global _doc, _diagram_type

        body, err = self._read_json_body()
        presented = self._presented_session()
        if not self._session_is_current(presented):
            self._send_stale()
            return
        if err is not None:
            self._send_json(
                200,
                {"ok": False, "preview": False, "saved": False, "errors": [err]},
            )
            return

        if not isinstance(body, dict):
            self._send_json(
                200,
                {
                    "ok": False,
                    "preview": False,
                    "saved": False,
                    "errors": ["body must be a JSON object"],
                },
            )
            return
        candidate, sidecar_in, split_err = _split_edit_body(body)
        if split_err:
            self._send_json(
                200,
                {"ok": False, "preview": False, "saved": False, "errors": [split_err]},
            )
            return

        errors = structural_check(candidate)
        if errors:
            self._send_json(
                200,
                {"ok": False, "preview": False, "saved": False, "errors": errors},
            )
            return

        with _state_lock:
            archify = _archify_path
            trailing = _had_trailing_newline
            dtype = resolve_diagram_type(candidate, _diagram_type)
            evidence_dir = _file_path.parent if _file_path is not None else None
            if sidecar_in is not None:
                sc = copy.deepcopy(sidecar_in)
            else:
                sc = copy.deepcopy(_sidecar)

        if not archify:
            with _state_lock:
                if not session_matches(presented):
                    self._send_stale()
                    return
                _diagram_type = dtype
                _doc = candidate
                _remember_sidecar(candidate, sc)
            self._send_json(
                200,
                {
                    "ok": True,
                    "preview": True,
                    "saved": False,
                    "structural": True,
                },
            )
            return

        ok_p, v_errors, html, note, layout = preview_candidate(
            archify, dtype, candidate, trailing, sc, evidence_dir
        )
        if not ok_p:
            self._send_json(
                200,
                {
                    "ok": False,
                    "preview": False,
                    "saved": False,
                    "errors": v_errors,
                },
            )
            return

        with _state_lock:
            if not session_matches(presented):
                self._send_stale()
                return
            _diagram_type = dtype
            _doc = candidate
            _remember_sidecar(candidate, sc)
            if html is not None:
                set_preview_html(html)

        receipt: dict[str, Any] = {
            "ok": True,
            "preview": True,
            "saved": False,
            "structural": True,
        }
        if note:
            receipt["note"] = note
        if layout is not None:
            receipt["layout"] = layout
        self._send_json(200, receipt)

    def _handle_type_library_save(self) -> None:
        """Upsert one type into the user library. Does not write the diagram."""
        body, err = self._read_json_body()
        if err is not None:
            self._send_json(200, {"ok": False, "error": err})
            return
        if not isinstance(body, dict):
            self._send_json(200, {"ok": False, "error": "body must be a JSON object"})
            return
        raw = body.get("type") if isinstance(body.get("type"), dict) else body
        if not isinstance(raw, dict):
            self._send_json(200, {"ok": False, "error": "type must be an object"})
            return
        lib, note = save_type_in_library(raw)
        if lib is None:
            self._send_json(200, {"ok": False, "error": note or "type library write failed"})
            return
        payload: dict[str, Any] = {"ok": True, "library": lib}
        if note:
            payload["note"] = note
        self._send_json(200, payload)

    def _handle_pick(self) -> None:
        """Native OS dialog via tkinter subprocess (M12). mode=save asks where to write."""
        mode = "open"
        save_type = ""
        file_type = "diagram"
        initial_file: str | None = None
        length = int(self.headers.get("Content-Length") or "0")
        if length:
            body, err = self._read_json_body()
            if err is None and isinstance(body, dict):
                if body.get("mode") == "save":
                    mode = "save"
                asked = body.get("diagram_type")
                if isinstance(asked, str):
                    save_type = asked
                asked_ft = body.get("file_type")
                if isinstance(asked_ft, str) and asked_ft.strip().lower() in (
                    "html",
                    "diagram",
                ):
                    file_type = asked_ft.strip().lower()
                asked_name = body.get("initial_file")
                if isinstance(asked_name, str) and asked_name.strip():
                    initial_file = asked_name.strip()
        with _state_lock:
            current = _file_path
            if save_type not in ("workflow", "architecture"):
                save_type = _diagram_type
        if current is not None:
            initial_dir = str(current.parent)
        else:
            initial_dir = str(Path.cwd())
        try:
            if mode == "save" and file_type == "html":
                html_name = initial_file or (
                    export_html_path(current).name if current is not None else "diagram.html"
                )
                result = native_save_html_path(initial_dir, html_name)
            elif mode == "save":
                result = native_save_path(
                    initial_dir, save_type, initial_file=initial_file
                )
            else:
                result = native_pick_path(initial_dir)
        except Exception:
            result = {"ok": False, "error": "native picker unavailable"}
        self._send_json(200, result)

    def _handle_new(self) -> None:
        """Replace the session with a blank seed or a template. No path. Does not write a file."""
        global _file_path, _diagram_type, _doc, _had_trailing_newline
        global _sidecar, _sidecar_note, _sidecar_unreadable
        dtype = "workflow"
        template_id = ""
        length = int(self.headers.get("Content-Length") or "0")
        if length:
            body, err = self._read_json_body()
            if err is None and isinstance(body, dict):
                asked = body.get("diagram_type")
                if isinstance(asked, str) and asked in ("workflow", "architecture"):
                    dtype = asked
                asked_template = body.get("template")
                if isinstance(asked_template, str):
                    template_id = asked_template.strip()
        presented = self._presented_session()
        if not self._session_is_current(presented):
            self._send_stale()
            return
        if template_id:
            doc = template_document(template_id)
            if doc is None:
                self._send_json(200, {"ok": False, "error": "unknown template"})
                return
            dtype = resolve_diagram_type(doc, dtype)
        else:
            doc = blank_diagram(dtype)
        sc = empty_sidecar()
        with _state_lock:
            if not session_matches(presented):
                self._send_stale()
                return
            _file_path = None
            _diagram_type = dtype
            _doc = doc
            _remember_absent_empty_keys(doc)
            _had_trailing_newline = True
            _sidecar = sc
            _sidecar_note = None
            _sidecar_unreadable = False
            bump_session()
            archify = _archify_path
            set_preview_html(None)
        if archify:
            rendered = deliver_preview_doc(archify, dtype, doc, True, sc)
            html, note = rendered if isinstance(rendered, tuple) else (None, "preview failed")
            with _state_lock:
                if isinstance(note, str) and note.strip():
                    _sidecar_note = note
                if html is not None:
                    set_preview_html(html)
        with _state_lock:
            payload = state_payload()
        payload["ok"] = True
        self._send_json(200, payload)

    def _handle_brand_rescan(self) -> None:
        """Rescan catalog.json and bendwright-data/icons. Does not raise."""
        with _state_lock:
            archify = _archify_path
        try:
            load_archify_catalog(archify)
        except Exception:
            pass
        note = scan_user_icons()
        payload: dict[str, Any] = {
            "ok": True,
            "brands": brands_api_payload(),
            "catalog": list(_catalog_marks),
            "catalog_ok": bool(_catalog_marks),
        }
        notes = [item for item in (_catalog_note, note) if item]
        if notes:
            payload["note"] = "\n".join(notes)
        self._send_json(200, payload)

    def _handle_open(self) -> None:
        """Switch the active diagram file (M10). Keeps current file on any failure."""
        global _file_path, _diagram_type, _doc, _had_trailing_newline
        global _sidecar, _sidecar_note, _sidecar_unreadable

        body, err = self._read_json_body()
        presented = self._presented_session()
        if not self._session_is_current(presented):
            self._send_stale()
            return
        if err is not None:
            self._send_json(400, {"ok": False, "error": err})
            return
        if not isinstance(body, dict):
            self._send_json(400, {"ok": False, "error": "body must be a JSON object"})
            return
        raw_path = body.get("path")
        if not isinstance(raw_path, str) or not raw_path.strip():
            self._send_json(400, {"ok": False, "error": "path is required"})
            return
        try:
            target = Path(raw_path).resolve()
        except (OSError, RuntimeError) as e:
            self._send_json(400, {"ok": False, "error": f"bad path: {e}"})
            return
        if not target.is_file():
            self._send_json(400, {"ok": False, "error": f"file not found: {target}"})
            return
        try:
            raw_text = target.read_text(encoding="utf-8")
        except OSError as e:
            self._send_json(400, {"ok": False, "error": f"cannot read file: {e}"})
            return
        trailing = raw_text.endswith("\n")
        try:
            doc = json.loads(raw_text)
        except json.JSONDecodeError as e:
            self._send_json(400, {"ok": False, "error": f"invalid JSON: {e}"})
            return
        if not isinstance(doc, dict):
            self._send_json(400, {"ok": False, "error": "IR root must be a JSON object"})
            return
        dtype = doc.get("diagram_type")
        if not isinstance(dtype, str) or not dtype.strip():
            self._send_json(400, {"ok": False, "error": "missing diagram_type"})
            return
        if dtype not in ("workflow", "architecture"):
            self._send_json(
                400,
                {
                    "ok": False,
                    "error": (
                        f"{dtype} diagrams are not supported yet - "
                        "workflow or architecture only"
                    ),
                },
            )
            return

        sc, sc_note, sc_bad = load_sidecar(target, doc)
        with _state_lock:
            if not session_matches(presented):
                self._send_stale()
                return
            archify = _archify_path
            _file_path = target
            _diagram_type = dtype
            _doc = doc
            _remember_absent_empty_keys(doc)
            _had_trailing_newline = trailing
            _sidecar = sc
            _sidecar_note = sc_note
            _sidecar_unreadable = sc_bad
            bump_session()
            set_preview_html(None)

        if archify:
            rendered = deliver_saved_file(archify, dtype, target, None, sc)
            html = rendered[0] if isinstance(rendered, tuple) else None
            deliver_note = rendered[1] if isinstance(rendered, tuple) else None
            miss = _markup_miss_from_note(deliver_note if isinstance(deliver_note, str) else None)
            with _state_lock:
                if miss:
                    _sidecar_note = _join_notes(_sidecar_note, miss)
                if html is not None:
                    set_preview_html(html)
                else:
                    set_preview_html(None)

        with _state_lock:
            payload = state_payload()
        self._send_json(200, payload)


# Mark geometry from docs/img/bendwright.svg (CC0). Inlined; no file read.
# Header uses currentColor. Favicon is #1B2A38 on a transparent background.
_MARK_SVG_BODY = (
    '<path fill="none" stroke="currentColor" stroke-width="56" '
    'stroke-linecap="butt" stroke-linejoin="miter" '
    'd="M 220 260 H 620 V 764 H 804"/>'
    '<circle cx="220" cy="260" r="78"/>'
    '<circle cx="620" cy="512" r="78"/>'
    '<circle cx="804" cy="764" r="78"/>'
)


def _mark_svg(paint: str, *, decorative: bool) -> str:
    hidden = ' aria-hidden="true" focusable="false"' if decorative else ""
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"{hidden}>'
        f'<g fill="{paint}" color="{paint}">'
        f"{_MARK_SVG_BODY}"
        "</g></svg>"
    )


_FAVICON_SVG = _mark_svg("#1B2A38", decorative=False).encode("utf-8")
_HEADER_MARK_SVG = _mark_svg("currentColor", decorative=True)


