def _hunk_set_sha(specs: tuple[dict[str, Any], ...]) -> str:
    payload = [
        {"path": spec["path"], "anchors": spec["anchors"]}
        for spec in specs
    ]
    raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _read_patch_state() -> dict[str, Any]:
    path = archify_patch_state_path()
    try:
        data = json.loads(path.read_bytes().decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return {"hunks": {}}
    if not isinstance(data, dict):
        return {"hunks": {}}
    if not isinstance(data.get("hunks"), dict):
        data["hunks"] = {}
    return data


def _write_bytes_atomic(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    os.close(fd)
    tmp_path = Path(tmp)
    try:
        tmp_path.write_bytes(data)
        os.replace(tmp_path, path)
    finally:
        if tmp_path.exists():
            _unlink_quiet(tmp_path)


def _write_patch_state(data: dict[str, Any]) -> None:
    raw = json.dumps(data, indent=2, ensure_ascii=False).encode("utf-8") + b"\n"
    _write_bytes_atomic(archify_patch_state_path(), raw)


def _sha_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _dir_writable(directory: Path) -> bool:
    """Create-and-delete probe. False on EACCES or a read-only tree."""
    try:
        directory.mkdir(parents=True, exist_ok=True)
        fd, probe = tempfile.mkstemp(prefix=".bw-write-", dir=str(directory))
        os.close(fd)
        os.unlink(probe)
        return True
    except OSError:
        return False


def _backup_path(path: Path) -> Path:
    return path.parent / f"{path.name}{_ARCHIFY_PATCH_BACKUP_SUFFIX}"


def _anchors_applied(text: str, anchors: tuple[tuple[str, str], ...]) -> bool:
    """True when every replacement string is already in the file."""
    return all(new in text for _old, new in anchors)


def _anchors_partial(text: str, anchors: tuple[tuple[str, str], ...]) -> bool:
    present = [new in text for _old, new in anchors]
    return any(present) and not all(present)


def _replace_anchors(
    text: str, anchors: tuple[tuple[str, str], ...]
) -> tuple[str | None, str | None]:
    """Apply every anchor once. Counts are taken on the original text."""
    for index, (old, new) in enumerate(anchors):
        count = text.count(old)
        if count != 1:
            return None, f"anchor {index} matched {count} times"
        if old == new:
            return None, f"anchor {index} is a no-op"
    out = text
    for old, new in anchors:
        out = out.replace(old, new, 1)
    return out, None


def _read_utf8(path: Path) -> str | None:
    try:
        return path.read_bytes().decode("utf-8")
    except (OSError, UnicodeError):
        return None


def _spec_patched_text(
    root: Path, spec: dict[str, Any], disk_text: str
) -> tuple[str | None, str | None]:
    """Apply anchors to the live file, or to its .bendwright-orig backup.

    A previous hunk set already replaced the stock anchors. Re-apply reads
    the backup (the original bytes unpatch restores) and does not rewrite it.
    """
    anchors = spec["anchors"]
    rel = spec["path"]
    if _anchors_applied(disk_text, anchors):
        return disk_text, None
    updated, err = _replace_anchors(disk_text, anchors)
    if updated is not None:
        return updated, None
    backup_text = _read_utf8(_backup_path(root / rel))
    if backup_text is not None and backup_text != disk_text:
        updated, backup_err = _replace_anchors(backup_text, anchors)
        if updated is not None:
            return updated, None
        err = f"{err}; backup {backup_err}"
    if _anchors_partial(disk_text, anchors):
        return None, f"anchor partial in {rel}"
    return None, f"anchor miss in {rel}: {err}"


def _hash_map(root: Path, rels: tuple[str, ...]) -> dict[str, str] | None:
    found: dict[str, str] = {}
    for rel in rels:
        path = root / rel
        try:
            found[rel] = _sha_bytes(path.read_bytes())
        except OSError:
            return None
    return found


def _record_patch_failure(
    hunk_sha: str,
    root: Path,
    version: str | None,
    current: dict[str, str],
    note: str,
) -> None:
    """Remember this file-hash set so startup does not retry until it changes."""
    try:
        state = _read_patch_state()
        hunks = state.setdefault("hunks", {})
        record = hunks.get(hunk_sha)
        if not isinstance(record, dict):
            record = {}
        record["root"] = str(root)
        record["archify_version"] = version
        record["failure_hashes"] = current
        record["failure_note"] = note
        hunks[hunk_sha] = record
        _write_patch_state(state)
    except OSError:
        return


def _smoke_kind_html(html: str) -> str | None:
    """Shared label checks. None when the delivered page shows the custom kind."""
    label = _SMOKE_KIND_LABEL
    if html.count(f'data-node-kind-label="{label}"') < 1:
        return "missing data-node-kind-label"
    if 'data-node-kind="backend"' not in html:
        return "base data-node-kind missing"
    if html.count(f'data-legend-kind="{label}"') != 1:
        return f"expected one {label} legend row"
    if f'data-legend-label="{label}"' not in html:
        return "legend label is not the raw label"
    if "bw-kind-swatch" not in html or "#6CB4F5" not in html or "#0072B2" not in html:
        return "theme swatch missing"
    passport = (
        "node.getAttribute('data-node-kind-label') || "
        "viewerKindLabel(node.getAttribute('data-node-kind') || 'node')"
    )
    if passport not in html:
        return "passport does not prefer the label attr"
    finder = (
        "function semanticType(node) {\n"
        "        var labeled = node.getAttribute('data-node-kind-label');"
    )
    if finder not in html:
        return "finder semanticType does not prefer the label attr"
    if "var typeLabel = item.node.getAttribute('data-node-kind-label')" not in html:
        return "finder meta title-cases the custom label"
    lens = (
        "var labeled = node.getAttribute('data-node-kind-label');\n"
        "          var value = labeled || node.getAttribute('data-node-kind') || 'neutral';"
    )
    if lens not in html:
        return "lens does not group by the label attr"
    return None


def _smoke_kind_deliver(
    archify_mjs: str, diagram_type: str, doc: dict[str, Any], map_path: str
) -> str | None:
    fd, fixture = tempfile.mkstemp(prefix=f"{APP}-smoke-", suffix=".json")
    os.close(fd)
    fd, html_path = tempfile.mkstemp(prefix=f"{APP}-smoke-", suffix=".html")
    os.close(fd)
    try:
        Path(fixture).write_text(json.dumps(doc), encoding="utf-8")
        try:
            proc = subprocess.run(
                ["node", archify_mjs, "deliver", diagram_type, fixture, html_path, "--json"],
                capture_output=True,
                text=True,
                timeout=120,
                check=False,
                env={
                    **os.environ,
                    "ARCHIFY_BENDWRIGHT_KINDS": map_path,
                    "ARCHIFY_BRAND_ALLOW_PRIVATE": "1",
                },
            )
        except (OSError, subprocess.TimeoutExpired) as e:
            return f"deliver failed: {e}"
        stdout = proc.stdout or ""
        stderr = proc.stderr or ""
        try:
            parsed = json.loads(stdout.strip()) if stdout.strip() else None
        except json.JSONDecodeError:
            parsed = None
        if not isinstance(parsed, dict) or not parsed.get("ok"):
            tail = (stderr or stdout).strip().splitlines()
            detail = tail[-1][:240] if tail else "deliver failed"
            return f"deliver failed: {detail}"
        try:
            html = Path(html_path).read_text(encoding="utf-8")
        except (OSError, UnicodeError) as e:
            return f"could not read smoke html: {e}"
        return _smoke_kind_html(html)
    finally:
        _unlink_quiet(fixture)
        _unlink_quiet(html_path)


def _smoke_kind_patch(archify_mjs: str) -> str | None:
    """None when workflow and architecture fixtures both show the label.

    Requires data-node-kind-label, the passport/finder/lens label path, and
    one in-drawing legend row. Architecture is schema 1 and must still splice
    the custom row. Does not go through run_archify.
    """
    if not shutil.which("node"):
        return "node not on PATH"
    workflow_doc = {
        "schema_version": 2,
        "diagram_type": "workflow",
        "meta": {"title": "Bendwright kind smoke", "animation": "none"},
        "lanes": [{"id": "lane", "label": "Lane"}],
        "nodes": [
            {
                "id": "vm",
                "lane": "lane",
                "col": 0,
                "type": "backend",
                "label": "Guest",
            }
        ],
        "edges": [],
    }
    architecture_doc = {
        "schema_version": 1,
        "diagram_type": "architecture",
        "meta": {"title": "Bendwright kind smoke", "animation": "none"},
        "components": [
            {
                "id": "vm",
                "type": "backend",
                "label": "Guest",
                "pos": [40, 80],
                "size": [160, 72],
            }
        ],
    }
    kind_map = {
        "vm": {
            "label": _SMOKE_KIND_LABEL,
            "colorDark": "#6CB4F5",
            "colorLight": "#0072B2",
        }
    }
    fd, map_path = tempfile.mkstemp(prefix=f"{APP}-kinds-", suffix=".json")
    os.close(fd)
    try:
        Path(map_path).write_text(json.dumps(kind_map), encoding="utf-8")
        workflow_reason = _smoke_kind_deliver(
            archify_mjs, "workflow", workflow_doc, map_path
        )
        if workflow_reason:
            return f"workflow: {workflow_reason}"
        architecture_reason = _smoke_kind_deliver(
            archify_mjs, "architecture", architecture_doc, map_path
        )
        if architecture_reason:
            return f"architecture: {architecture_reason}"
        return None
    finally:
        _unlink_quiet(map_path)


def _restore_texts(root: Path, originals: dict[str, str]) -> None:
    for rel, text in originals.items():
        _write_bytes_atomic(root / rel, text.encode("utf-8"))


def apply_archify_kind_patch(archify_mjs: str | None) -> str:
    """Patch the resolved tree. Never raises. Sets the status globals."""
    global _archify_patch_note, _archify_patch_state
    try:
        note, state = _apply_archify_kind_patch(archify_mjs)
    except Exception as e:
        note = f"archify patch: not patched (patch error: {e})"
        state = "unpatched"
    _archify_patch_note = note
    _archify_patch_state = state
    return note


def _apply_archify_kind_patch(archify_mjs: str | None) -> tuple[str, str]:
    if os.environ.get("ARCHIFY_BENDWRIGHT_PATCH", "").strip() == "0":
        return "archify patch: opted out", "opted-out"
    if not archify_mjs:
        return "archify patch: not patched (no archify.mjs)", "unpatched"
    root = archify_skill_root(archify_mjs)
    version = read_installed_archify_version(archify_mjs)
    specs = _archify_patch_specs()
    rels = tuple(spec["path"] for spec in specs)
    hunk_sha = _hunk_set_sha(specs)
    current = _hash_map(root, rels)
    if current is None:
        missing = next((rel for rel in rels if not (root / rel).is_file()), rels[0])
        return f"archify patch: not patched (missing {missing})", "unpatched"

    state = _read_patch_state()
    record = state.get("hunks", {}).get(hunk_sha)
    if isinstance(record, dict):
        patched = record.get("patched_hashes")
        failed = record.get("failure_hashes")
        if patched == current:
            return "archify patch: patched", "patched"
        if isinstance(failed, dict) and failed == current:
            reason = record.get("failure_note") or "previous attempt failed"
            return f"archify patch: not patched ({reason})", "unpatched"

    version_bit = f"archify {version}" if version else "archify version unknown"
    if not _dir_writable(root):
        return (
            f"archify patch: not patched (archify patch skipped: {root} not writable)",
            "unpatched",
        )

    originals: dict[str, str] = {}
    patched_text: dict[str, str] = {}
    for spec in specs:
        rel = spec["path"]
        try:
            text = (root / rel).read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as e:
            return f"archify patch: not patched (could not read {rel}: {e})", "unpatched"
        originals[rel] = text
        updated, err = _spec_patched_text(root, spec, text)
        if updated is None:
            note = err or f"anchor miss in {rel}"
            _record_patch_failure(hunk_sha, root, version, current, note)
            return f"archify patch: not patched ({note}; custom names shown in tooltips and page legend only)", "unpatched"
        patched_text[rel] = updated

    wrote: list[str] = []
    try:
        for rel, text in originals.items():
            if patched_text[rel] == text:
                continue
            backup = _backup_path(root / rel)
            if not backup.exists():
                _write_bytes_atomic(backup, text.encode("utf-8"))
        for rel, text in patched_text.items():
            if text == originals[rel]:
                continue
            _write_bytes_atomic(root / rel, text.encode("utf-8"))
            wrote.append(rel)
        reason = _smoke_kind_patch(archify_mjs)
        if reason:
            _restore_texts(root, originals)
            note = f"smoke failed: {reason}"
            _record_patch_failure(hunk_sha, root, version, current, note)
            return f"archify patch: not patched ({note}; custom names shown in tooltips and page legend only)", "unpatched"
        marker = root / _ARCHIFY_PATCH_MARKER
        _write_bytes_atomic(marker, f"{hunk_sha}\n".encode("utf-8"))
        patched_hashes = _hash_map(root, rels)
        if patched_hashes is None:
            raise OSError("patched files disappeared")
        # orig hashes are the backup bytes unpatch will restore.
        orig_hashes = {
            rel: _sha_bytes(_backup_path(root / rel).read_bytes()) for rel in rels
        }
        hunks = state.setdefault("hunks", {})
        hunks[hunk_sha] = {
            "root": str(root),
            "archify_version": version,
            "orig_hashes": orig_hashes,
            "patched_hashes": patched_hashes,
            "failure_hashes": None,
            "failure_note": None,
        }
        _write_patch_state(state)
    except OSError as e:
        if wrote:
            try:
                _restore_texts(root, originals)
            except OSError:
                pass
        _unlink_quiet(root / _ARCHIFY_PATCH_MARKER)
        note = f"archify patch skipped: {e}"
        return f"archify patch: not patched ({note})", "unpatched"
    return f"archify patch: applied now ({version_bit})", "applied"


def _matching_patch_record(state: dict[str, Any], root: Path, current: dict[str, str]) -> dict[str, Any] | None:
    hunks = state.get("hunks")
    if not isinstance(hunks, dict):
        return None
    root_s = str(root)
    fallback: dict[str, Any] | None = None
    for record in hunks.values():
        if not isinstance(record, dict):
            continue
        if record.get("patched_hashes") != current:
            continue
        if record.get("root") in (None, root_s):
            return record
        fallback = record
    return fallback


def unpatch_archify_main(cli_path: str | None) -> int:
    """Restore backups only when current hashes equal the recorded patched hashes."""
    try:
        archify, _detail = detect_archify(cli_path)
        if not archify:
            print(f"[{APP}] archify unpatch refused: no archify.mjs found", flush=True)
            return 2
        root = archify_skill_root(archify)
        specs = _archify_patch_specs()
        rels = tuple(spec["path"] for spec in specs)
        current = _hash_map(root, rels)
        if current is None:
            print(f"[{APP}] archify unpatch refused: patch targets missing in {root}", flush=True)
            return 2
        state = _read_patch_state()
        record = _matching_patch_record(state, root, current)
        if record is None:
            print(
                f"[{APP}] archify unpatch refused: current files do not match the recorded patched hashes",
                flush=True,
            )
            return 2
        orig = record.get("orig_hashes")
        if not isinstance(orig, dict):
            print(
                f"[{APP}] archify unpatch refused: recorded patch has no original hashes",
                flush=True,
            )
            return 2
        payloads: dict[str, bytes] = {}
        for rel in rels:
            backup = _backup_path(root / rel)
            if not backup.is_file():
                print(
                    f"[{APP}] archify unpatch refused: backup missing for {rel}",
                    flush=True,
                )
                return 2
            data = backup.read_bytes()
            if _sha_bytes(data) != orig.get(rel):
                print(
                    f"[{APP}] archify unpatch refused: backup does not match the recorded original for {rel}",
                    flush=True,
                )
                return 2
            payloads[rel] = data
        if not _dir_writable(root):
            print(
                f"[{APP}] archify unpatch refused: {root} not writable",
                flush=True,
            )
            return 2
        for rel, data in payloads.items():
            _write_bytes_atomic(root / rel, data)
        marker = root / _ARCHIFY_PATCH_MARKER
        if marker.exists():
            _unlink_quiet(marker)
        print(f"[{APP}] archify unpatch: restored {len(rels)} files in {root}", flush=True)
        return 0
    except Exception as e:
        print(f"[{APP}] archify unpatch refused: {e}", flush=True)
        return 2


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
SUPPORTED_TYPES = {
    "workflow": "workflow",
    "architecture": "architecture",
}


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    p = argparse.ArgumentParser(
        prog=APP,
        description=(
            "Local offline editor for Archify diagram IR JSON. "
            "User data (icons, type library, archify patch state) lives in "
            "bendwright-data/ next to this script. Set BENDWRIGHT_DATA_DIR to "
            "an absolute path to override."
        ),
    )
    p.add_argument(
        "type_or_path",
        nargs="?",
        default=None,
        help='diagram type ("workflow" or "architecture") or path to IR JSON; omit both for empty start',
    )
    p.add_argument(
        "path",
        nargs="?",
        default=None,
        help="path to the IR JSON file (when type is given first)",
    )
    p.add_argument(
        "--type",
        dest="type_override",
        default=None,
        help="diagram type override (otherwise inferred from the file)",
    )
    p.add_argument(
        "--archify",
        default=None,
        help="path to archify.mjs (explicit override; auto-detect otherwise)",
    )
    p.add_argument(
        "--port",
        type=int,
        default=8770,
        help="preferred loopback port (default 8770; if busy, the next ports through 8789)",
    )
    p.add_argument(
        "--keep-alive",
        action="store_true",
        help="disable auto-exit when the browser disconnects (SSE presence still served)",
    )
    p.add_argument(
        "--unpatch-archify",
        action="store_true",
        help="restore the resolved archify tree from .bendwright-orig backups",
    )
    return p.parse_args(argv)


def _presence_watchdog() -> None:
    """Shut down only after every /api/alive connection has been gone for GRACE.

    Does not arm on GET / and never takes _state_lock. --keep-alive disables this.
    """
    global _httpd
    while True:
        time.sleep(1.0)
        if not _auto_exit:
            continue
        with _alive_lock:
            seen = _alive_seen
            active = _alive
            zero_ts = _last_zero_ts
        if not seen or active != 0 or zero_ts is None:
            continue
        if (time.monotonic() - zero_ts) > ALIVE_GRACE_S:
            httpd = _httpd
            if httpd is not None:
                httpd.shutdown()
            return


def _wait_http_ready(port: int) -> bool:
    """True once GET /api/brands answers, so archify can fetch brand PNGs."""
    deadline = time.time() + 5.0
    url = f"http://127.0.0.1:{port}/api/brands"
    while time.time() < deadline:
        try:
            with urllib.request.urlopen(url, timeout=0.3) as resp:
                if getattr(resp, "status", 200) == 200:
                    return True
        except (OSError, urllib.error.URLError, TimeoutError):
            time.sleep(0.05)
    return False


def main(argv: list[str] | None = None) -> int:
    global _file_path, _diagram_type, _doc, _had_trailing_newline, _archify_path, _httpd, _auto_exit, _listen_port
    global _sidecar, _sidecar_note, _sidecar_unreadable, _session_gen

    args = parse_args(argv)
    migrate_legacy_data_dir()
    if args.unpatch_archify:
        return unpatch_archify_main(args.archify)
    known = ", ".join(sorted(SUPPORTED_TYPES))
    file_path: Path | None = None
    dtype: str | None = None

    if args.path is not None:
        # Legacy: python bendwright.py workflow path.json
        if args.type_or_path not in SUPPORTED_TYPES:
            print(
                f"[{APP}] unknown type {args.type_or_path!r}; known: {known}",
                file=sys.stderr,
            )
            return 2
        dtype = SUPPORTED_TYPES[args.type_or_path]
        file_path = Path(args.path).resolve()
    elif args.type_or_path is not None:
        # One positional: path.json (or a bare type without path → error)
        token = args.type_or_path
        as_path = Path(token)
        if token in SUPPORTED_TYPES and not as_path.is_file():
            print(
                f"[{APP}] path required when type is given (got type {token!r} only)",
                file=sys.stderr,
            )
            return 2
        file_path = as_path.resolve()
    # else: no-arg empty start

    if args.type_override is not None and args.type_override not in SUPPORTED_TYPES:
        print(
            f"[{APP}] unknown --type {args.type_override!r}; known: {known}",
            file=sys.stderr,
        )
        return 2

    note_data_dir_writable()
    _archify_path, archify_msg = detect_archify(args.archify)
    note_archify_version(_archify_path)
    load_archify_catalog(_archify_path)
    icon_note = scan_user_icons()
    apply_archify_kind_patch(_archify_path)
    set_preview_html(None)
    print(f"[{APP}] archify: {archify_msg}", flush=True)
    if _archify_version_note:
        print(f"[{APP}] {_archify_version_note}", flush=True)
    if _archify_patch_note:
        print(f"[{APP}] {_archify_patch_note}", flush=True)
    if _data_dir_note:
        print(f"[{APP}] {_data_dir_note}", flush=True)
    if _catalog_note:
        print(f"[{APP}] {_catalog_note}", flush=True)
    if icon_note:
        print(f"[{APP}] {icon_note}", flush=True)

    if file_path is not None:
        if not file_path.is_file():
            print(f"[{APP}] file not found: {file_path}", file=sys.stderr)
            return 2
        doc, trailing = load_doc(file_path)
        if args.type_override is not None:
            dtype = SUPPORTED_TYPES[args.type_override]
        elif dtype is None:
            inferred = doc.get("diagram_type")
            if not isinstance(inferred, str) or not inferred.strip():
                print(
                    f"[{APP}] missing diagram_type in {file_path}",
                    file=sys.stderr,
                )
                return 2
            if inferred not in SUPPORTED_TYPES:
                print(
                    f"[{APP}] unsupported diagram_type {inferred!r}; known: {known}",
                    file=sys.stderr,
                )
                return 2
            dtype = SUPPORTED_TYPES[inferred]
        _file_path = file_path
        _diagram_type = dtype
        _doc = doc
        _remember_absent_empty_keys(doc)
        _had_trailing_newline = trailing
        _sidecar, _sidecar_note, _sidecar_unreadable = load_sidecar(file_path, doc)
    else:
        _file_path = None
        if args.type_override is not None:
            _diagram_type = SUPPORTED_TYPES[args.type_override]
        else:
            _diagram_type = "workflow"
        _doc = blank_diagram(_diagram_type)
        _remember_absent_empty_keys(_doc)
        _had_trailing_newline = True
        _sidecar = empty_sidecar()
        _sidecar_note = None
        _sidecar_unreadable = False

    # Bind before the initial deliver so archify can fetch /brand/<name>.png.
    # --port is the first port tried. If it is in use, take the next free
    # port in 8770..8789. A hard bind error still stops on that port.
    _session_gen = 1
    server, bind_err = bind_loopback(args.port)
    if server is None:
        print(
            f"[{APP}] cannot bind 127.0.0.1:{args.port}: {bind_err}",
            file=sys.stderr,
        )
        return 2
    server.daemon_threads = True
    _httpd = server
    _listen_port = int(server.server_address[1])
    serve_thread = threading.Thread(target=server.serve_forever, name="bendwright-http")
    serve_thread.start()
    try:
        if not _wait_http_ready(_listen_port):
            print(
                f"[{APP}] HTTP server did not accept connections on port {_listen_port}",
                file=sys.stderr,
            )

        if _archify_path and isinstance(_doc, dict) and _doc:
            if file_path is not None:
                rendered = deliver_saved_file(
                    _archify_path, _diagram_type, file_path, None, _sidecar
                )
            else:
                rendered = deliver_preview_doc(
                    _archify_path, _diagram_type, _doc, True, _sidecar
                )
            html, note = rendered if isinstance(rendered, tuple) else (None, "deliver failed")
            miss = _markup_miss_from_note(note if isinstance(note, str) else None)
            with _state_lock:
                if html is not None:
                    set_preview_html(html)
                if miss:
                    _sidecar_note = _join_notes(_sidecar_note, miss)
            if html is not None:
                print(f"[{APP}] initial preview rendered", flush=True)
                if note:
                    print(f"[{APP}] {note}", flush=True)
            else:
                print(
                    f"[{APP}] initial preview unavailable: {note or 'deliver failed'}",
                    flush=True,
                )

        url = f"http://127.0.0.1:{_listen_port}/"
        if file_path is not None:
            print(f"[{APP}] {url}  editing {file_path}", flush=True)
        else:
            print(f"[{APP}] {url}  unsaved new diagram (Save to choose a path)", flush=True)
        _auto_exit = not args.keep_alive
        if args.keep_alive:
            print(f"[{APP}] auto-exit off (--keep-alive)", flush=True)
        try:
            webbrowser.open(url)
        except Exception:
            pass

        threading.Thread(target=_presence_watchdog, name="presence-watchdog", daemon=True).start()
        while serve_thread.is_alive():
            serve_thread.join(0.5)
    except KeyboardInterrupt:
        print(f"\n[{APP}] stopped", flush=True)
    finally:
        if serve_thread.is_alive():
            server.shutdown()
            serve_thread.join(timeout=5)
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
